let _toolPath = '';
let _activated = false;
const _sidebarRefreshCallbacks = [];
// ═══════════════════════════════════════════════════════════════════════════
// ── Preview and display copies (M104 Part C) ─────────────────────────────
// Phone footage and photos the renderer cannot decode play from copies made
// once into the thumbnail cache. Originals are never touched.
const MO_HEIC_RE = /\.(heic|heif)$/i;
const MO_PREVIEW_CODECS = new Set(['hevc', 'h265', 'vp8', 'mpeg4', 'mpeg2video', 'wmv3', 'vc1', 'prores']);
const _moCopyInflight = new Map();
function moPathKey(filePath, st) {
  const str = `${filePath}|${st && st.size}|${st && (st.mtime || st.mtimeMs || '')}`;
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  return h.toString(16).padStart(8, '0') + '-' + (Number(st && st.size) || 0).toString(36);
}
async function moCopyOnce(srcPath, subdir, ext, make, api) {
  const thumbDir = getThumbDir(api || _api);
  if (!thumbDir) return null;
  const st = await window.parallxElectron.fs.stat(srcPath).catch(() => null);
  if (!st || st.error) return null;
  const sep = _isWindows ? '\\' : '/';
  const dir = thumbDir + sep + subdir;
  const outPath = dir + sep + moPathKey(srcPath, st) + ext;
  if (await window.parallxElectron.fs.exists(outPath)) return outPath;
  if (_moCopyInflight.has(outPath)) return _moCopyInflight.get(outPath);
  const p = (async () => {
    try {
      await window.parallxElectron.fs.mkdir(dir);
      const ok = await make(outPath);
      if (ok) return outPath;
      await window.parallxElectron.fs.delete(outPath, { useTrash: false }).catch(() => {});
      return null;
    } catch (err) {
      console.warn('[media-organizer] copy failed:', srcPath, err && err.message);
      return null;
    } finally { _moCopyInflight.delete(outPath); }
  })();
  _moCopyInflight.set(outPath, p);
  return p;
}
// JPEG copy of a HEIC photo, through the bundled magick.
async function moHeicDisplayCopy(filePath, api) {
  if (!MO_HEIC_RE.test(filePath) || !_toolPaths.magick) return null;
  return moCopyOnce(filePath, 'converted', '.jpg', async (outPath) => {
    const m = shellInvoke(_toolPaths.magick);
    const r = await window.parallxElectron.terminal.exec(`${m} ${shellQuote(filePath)} -auto-orient -quality 92 ${shellQuote(outPath)}`, { timeout: 600000 });
    if (r.exitCode !== 0) console.warn(`[media-organizer] magick could not convert ${filePath}: ${r.stderr || r.stdout || ''}`);
    return r.exitCode === 0;
  }, api);
}
// H.264 preview copy of a video Chromium cannot decode, through ffmpeg.
async function moVideoPreviewCopy(videoPath, api) {
  if (!_toolPaths.ffmpeg) return null;
  return moCopyOnce(videoPath, 'previews', '.mp4', async (outPath) => {
    const r = await moExecFFArgs(['-y', '-hide_banner', '-loglevel', 'error', '-i', videoPath, '-vf', "scale='min(1280,iw)':-2", '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '26', '-pix_fmt', 'yuv420p', '-c:a', 'aac', '-b:a', '128k', '-movflags', '+faststart', outPath], 30 * 60 * 1000);
    return !!r && r.exitCode === 0;
  }, api);
}
// Some machines decode HEVC in hardware; then the file plays as it is.
function moCanPlayCodec(codec) {
  if (window.__moForcePreviewCopy) return false;
  const types = { hevc: 'video/mp4; codecs="hvc1.1.6.L93.B0"', h265: 'video/mp4; codecs="hvc1.1.6.L93.B0"' };
  const t = types[codec];
  if (!t) return false;
  try { return !!document.createElement('video').canPlayType(t); } catch { return false; }
}
async function moVideoCodecForPath(videoPath) {
  try {
    const sep = videoPath.includes('\\') ? '\\' : '/';
    const dir = videoPath.slice(0, videoPath.lastIndexOf(sep));
    const base = videoPath.slice(videoPath.lastIndexOf(sep) + 1);
    const row = await db.get(
      `SELECT vfi.codec FROM mo_files f JOIN mo_folders fo ON fo.id = f.folder_id
       JOIN mo_video_files vfi ON vfi.file_id = f.id
       WHERE f.basename = ? AND (fo.path = ? OR fo.path = ?)`, [base, dir, dir + sep]);
    return row && row.codec ? String(row.codec).toLowerCase() : null;
  } catch { return null; }
}
// What the clip editor auditions: the preview copy when the codec needs one, else the file itself.
async function moClipPreviewSource(videoPath, api) {
  const codec = await moVideoCodecForPath(videoPath);
  if (codec && MO_PREVIEW_CODECS.has(codec) && !moCanPlayCodec(codec)) { const p = await moVideoPreviewCopy(videoPath, api); if (p) return p; }
  return videoPath;
}

// Section 44: Practice (M104, docs/Parallx_Milestone_104.md)
//
// Timed drawing from the library. Daily Study and Practice Sessions are one
// engine with four parts: a pool (where pictures come from), a picker (random,
// favouring what has not been drawn for the longest time), a clock and a log.
// Everything here sits behind mediaOrganizer.enableArtTools (decision D7):
// off hides the surfaces and silences Daily Study; nothing is deleted.
// ═══════════════════════════════════════════════════════════════════════════

// @mo-practice-pure-begin — pure practice math (extracted verbatim by tests/unit/moPractice.test.ts)

// Small seeded generator (mulberry32) so picks are reproducible in tests.
function moPracticeRng(seed) {
  let a = (Number(seed) >>> 0) || 1;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Sizing arithmetic (decision D3). mode 'count': pictures × seconds each.
// mode 'total': total seconds ÷ seconds each, rounded down; the rest is spare.
function moPracticeSizing(input) {
  const secondsPer = Math.max(1, Math.floor(Number(input && input.secondsPer) || 0));
  const mode = input && input.mode === 'total' ? 'total' : 'count';
  if (mode === 'total') {
    const total = Math.max(0, Math.floor(Number(input.totalSeconds) || 0));
    const count = Math.floor(total / secondsPer);
    return { mode, secondsPer, count, totalSeconds: count * secondsPer, spareSeconds: total - count * secondsPer };
  }
  const count = Math.max(0, Math.floor(Number(input.count) || 0));
  return { mode, secondsPer, count, totalSeconds: count * secondsPer, spareSeconds: 0 };
}

// "45 s", "2 min", "2 min 30 s", "1 h 30 min"
function moPracticeFormatDuration(seconds) {
  const s = Math.max(0, Math.round(Number(seconds) || 0));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const r = s % 60;
  const parts = [];
  if (h) parts.push(h + ' h');
  if (m) parts.push(m + ' min');
  if (r && !h) parts.push(r + ' s');
  return parts.length ? parts.join(' ') : '0 s';
}

// "45 min at 2 min each = 22 pictures, 1 min to spare"
function moPracticeSizingText(sizing) {
  const z = moPracticeSizing(sizing);
  const pics = z.count === 1 ? '1 picture' : z.count + ' pictures';
  if (z.mode === 'total') {
    const total = z.totalSeconds + z.spareSeconds;
    const spare = z.spareSeconds ? ', ' + moPracticeFormatDuration(z.spareSeconds) + ' to spare' : '';
    return moPracticeFormatDuration(total) + ' at ' + moPracticeFormatDuration(z.secondsPer) + ' each = ' + pics + spare;
  }
  return pics + ' at ' + moPracticeFormatDuration(z.secondsPer) + ' each = ' + moPracticeFormatDuration(z.totalSeconds);
}

// The clock's face: m:ss, never negative.
function moPracticeClock(seconds) {
  const s = Math.max(0, Math.ceil(Number(seconds) || 0));
  return Math.floor(s / 60) + ':' + String(s % 60).padStart(2, '0');
}

// Oldest-first order. candidates: [{ id, lastDrawnAt }] where lastDrawnAt is
// epoch ms or null. Never-drawn pictures count as the oldest; ties are broken
// at random so equals do not always come out in id order.
function moPracticeOrder(candidates, rng) {
  const rand = typeof rng === 'function' ? rng : Math.random;
  const rows = (candidates || []).map((c) => ({ c, never: c.lastDrawnAt == null, at: Number(c.lastDrawnAt) || 0, r: rand() }));
  rows.sort((a, b) => {
    if (a.never !== b.never) return a.never ? -1 : 1;
    if (!a.never && a.at !== b.at) return a.at - b.at;
    return a.r - b.r;
  });
  return rows.map((x) => x.c);
}

// The picker: the n least-recently-drawn pictures, then shuffled so a run is
// not in history order. No repeats; fewer than n when the pool is small.
function moPracticePick(candidates, n, rng) {
  const rand = typeof rng === 'function' ? rng : Math.random;
  const want = Math.max(0, Math.floor(Number(n) || 0));
  const picked = moPracticeOrder(candidates, rand).slice(0, want);
  for (let i = picked.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    const t = picked[i]; picked[i] = picked[j]; picked[j] = t;
  }
  return picked;
}

// The neglected list: oldest first, in order, for the setup tab.
function moPracticeNeglected(candidates, limit, rng) {
  return moPracticeOrder(candidates, rng).slice(0, Math.max(0, Math.floor(Number(limit) || 0)));
}

// Local calendar day, YYYY-MM-DD. Daily Study keys on this.
function moPracticeDayKey(date) {
  const d = date instanceof Date ? date : new Date(date == null ? Date.now() : date);
  const p = (n) => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate());
}

// Totals for an end screen or a history row. draws: [{ outcome, planned_seconds, spent_seconds }]
function moPracticeSummary(draws) {
  const out = { shown: 0, done: 0, skipped: 0, plannedSeconds: 0, spentSeconds: 0 };
  for (const d of draws || []) {
    if (!d || d.outcome === 'pending') continue;
    out.shown++;
    if (d.outcome === 'done') out.done++;
    else if (d.outcome === 'skipped') out.skipped++;
    out.plannedSeconds += Math.max(0, Number(d.planned_seconds) || 0);
    out.spentSeconds += Math.max(0, Number(d.spent_seconds) || 0);
  }
  return out;
}
// @mo-practice-pure-end

let _artToolsEnabled = false;
let _practiceCfg = { dailyMinutes: 10, chime: true, mirror: false, greyscale: false };
const MO_ART_CFG_KEYS = ['enableArtTools', 'practiceDailyMinutes', 'practiceChime', 'practiceMirror', 'practiceGreyscale'];
const MO_PRACTICE_PER_OPTIONS = [30, 60, 120, 180, 300, 600, 900, 1200, 1800, 2700, 3600];
const MO_PRACTICE_TOTAL_OPTIONS = [10, 15, 20, 30, 45, 60, 90, 120];

function moReadArtCfg(api) {
  const cfg = api.workspace.getConfiguration('mediaOrganizer');
  _artToolsEnabled = cfg.get('enableArtTools', false) === true;
  const mins = parseInt(cfg.get('practiceDailyMinutes', 10), 10);
  _practiceCfg = {
    dailyMinutes: Number.isFinite(mins) && mins > 0 ? Math.min(180, mins) : 10,
    chime: cfg.get('practiceChime', true) !== false,
    mirror: cfg.get('practiceMirror', false) === true,
    greyscale: cfg.get('practiceGreyscale', false) === true,
  };
}

// The drawing and painting tools are opt-in. A command that needs them asks
// once, in place, and carries on if the user says yes — never a dead-end toast
// that sends them hunting through settings.
function moArtGate(api, retry) {
  if (_artToolsEnabled) return true;
  api = api || _api;
  void Promise.resolve(api.window.showInformationMessage(
    'Drawing and painting tools are off. Turn them on to use this.',
    { title: 'Turn On' },
  )).then(async (picked) => {
    if (!picked || picked.title !== 'Turn On') return;
    try { await api.workspace.getConfiguration('mediaOrganizer').update('enableArtTools', true); } catch { return; }
    _artToolsEnabled = true;
    if (typeof retry === 'function') retry();
  }).catch(() => {});
  return false;
}

function moPracticeDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  return d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
}

// ── Pools ──────────────────────────────────────────────────────────────────
// pool: { kind: 'all' | 'tag' | 'album' | 'search' | 'photos', id?, label?, query?, ids? }
// Stored as the question, not a list, so new photos join automatically.

function moPoolLabel(pool) {
  if (!pool || !pool.kind || pool.kind === 'all') return 'Everything';
  if (pool.kind === 'search') return 'Search: ' + (pool.query || '');
  if (pool.kind === 'photos') return pool.label || ((pool.ids || []).length === 1 ? '1 picture' : (pool.ids || []).length + ' pictures');
  return (pool.kind === 'tag' ? 'Tag: ' : 'Album: ') + (pool.label || '#' + pool.id);
}

async function moPoolPhotoIds(pool) {
  const kind = (pool && pool.kind) || 'all';
  let rows = [];
  if (kind === 'tag') {
    const ids = [Number(pool.id)];
    try { for (const t of (await TagQueries.getDescendants(Number(pool.id))) || []) ids.push(Number(t.id)); } catch { /* direct tag only */ }
    rows = await db.all(
      `SELECT DISTINCT pt.photo_id AS id FROM mo_photos_tags pt JOIN mo_photos p ON p.id = pt.photo_id
       WHERE p.deleted_at IS NULL AND pt.tag_id IN (${ids.map(() => '?').join(',')})`, ids);
  } else if (kind === 'album') {
    rows = await db.all(
      `SELECT DISTINCT ap.photo_id AS id FROM mo_albums_photos ap JOIN mo_photos p ON p.id = ap.photo_id
       WHERE p.deleted_at IS NULL AND ap.album_id = ?`, [Number(pool.id)]);
  } else if (kind === 'search') {
    const expr = moBuildFtsMatch(String(pool.query || '').trim());
    if (!expr) return [];
    const fts = await moFtsLookup(expr, 50000);
    const ids = (fts && fts.photoIds) || [];
    if (!ids.length) return [];
    const out = [];
    for (let i = 0; i < ids.length; i += 500) {
      const part = ids.slice(i, i + 500);
      const r = await db.all(`SELECT id FROM mo_photos WHERE deleted_at IS NULL AND id IN (${part.map(() => '?').join(',')})`, part);
      out.push(...r);
    }
    rows = out;
  } else if (kind === 'photos') {
    const ids = (pool.ids || []).map(Number).filter((x) => x > 0);
    if (!ids.length) return [];
    rows = await db.all(`SELECT id FROM mo_photos WHERE deleted_at IS NULL AND id IN (${ids.map(() => '?').join(',')})`, ids);
  } else {
    rows = await db.all('SELECT id FROM mo_photos WHERE deleted_at IS NULL');
  }
  const ids = rows.map((r) => Number(r.id)).filter((x) => x > 0);
  return moDropOfflinePhotos(ids);
}

// Pictures on a drive that is not connected cannot be drawn: leave them out
// of every pool until the drive is back.
async function moDropOfflinePhotos(ids) {
  if (!_moOfflineRoots.size || !ids.length) return ids;
  const keep = [];
  for (let i = 0; i < ids.length; i += 500) {
    const part = ids.slice(i, i + 500);
    const rows = await db.all(
      `SELECT pf.photo_id AS id, fo.path AS folder_path FROM mo_photos_files pf
       JOIN mo_files f ON f.id = pf.file_id JOIN mo_folders fo ON fo.id = f.folder_id
       WHERE pf.is_primary = 1 AND pf.photo_id IN (${part.map(() => '?').join(',')})`, part);
    const offline = new Set(rows.filter((r) => moFolderIsOffline(r.folder_path || '')).map((r) => Number(r.id)));
    for (const id of part) if (!offline.has(id)) keep.push(id);
  }
  return keep;
}

// photo id → epoch ms of the last time it was drawn, for the whole library.
async function moPracticeLastDrawnMap() {
  const map = new Map();
  const rows = await db.all(`SELECT photo_id, MAX(drawn_at) AS last FROM mo_practice_draws WHERE outcome != 'pending' AND drawn_at IS NOT NULL GROUP BY photo_id`);
  for (const r of rows) {
    const t = Date.parse(r.last);
    if (Number.isFinite(t)) map.set(Number(r.photo_id), t);
  }
  return map;
}

async function moPracticeCandidates(pool) {
  const [ids, last] = await Promise.all([moPoolPhotoIds(pool), moPracticeLastDrawnMap()]);
  return ids.map((id) => ({ id, lastDrawnAt: last.has(id) ? last.get(id) : null }));
}

// ── Sessions and the log ───────────────────────────────────────────────────

async function moPracticeCreateSession(spec) {
  const kind = spec.kind === 'daily' ? 'daily' : 'practice';
  const secondsPer = Math.max(1, Math.floor(Number(spec.secondsPer) || 0));
  const want = Math.max(1, Math.floor(Number(spec.count) || 0));
  const candidates = await moPracticeCandidates(spec.pool);
  if (!candidates.length) throw new Error('No pictures in this pool.');
  const picked = moPracticePick(candidates, want);
  const now = new Date().toISOString();
  const options = Object.assign({}, spec.options || {}, { count: want });
  const res = await db.run(
    `INSERT INTO mo_practice_sessions (kind, preset_id, pool_json, seconds_per, options_json, started_at, planned_seconds)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [kind, spec.presetId || null, JSON.stringify(spec.pool || { kind: 'all' }), secondsPer, JSON.stringify(options), now, picked.length * secondsPer]);
  const sessionId = res.lastInsertRowid;
  const ops = picked.map((c, i) => ({
    type: 'run',
    sql: 'INSERT INTO mo_practice_draws (session_id, photo_id, position, planned_seconds) VALUES (?, ?, ?, ?)',
    params: [sessionId, c.id, i, secondsPer],
  }));
  if (ops.length) await db.transaction(ops);
  document.dispatchEvent(new CustomEvent('mo:practice-changed'));
  return { id: sessionId, count: picked.length, shortfall: want - picked.length };
}

async function moPracticeLoadSession(id) {
  const session = await db.get('SELECT * FROM mo_practice_sessions WHERE id = ?', [id]);
  if (!session) return null;
  const draws = await db.all('SELECT * FROM mo_practice_draws WHERE session_id = ? ORDER BY position ASC', [id]);
  let pool = { kind: 'all' }; let options = {};
  try { pool = JSON.parse(session.pool_json) || pool; } catch { /* default */ }
  try { options = JSON.parse(session.options_json) || {}; } catch { /* default */ }
  return { session: Object.assign(session, { pool, options }), draws };
}

async function moPracticeUpdateDraw(id, d) {
  await db.run('UPDATE mo_practice_draws SET spent_seconds = ?, outcome = ?, drawn_at = ? WHERE id = ?',
    [Math.max(0, Math.round(Number(d.spent_seconds) || 0)), d.outcome || 'pending', d.drawn_at || null, id]);
}

async function moPracticeEndSession(id) {
  await db.transaction([
    { type: 'run', sql: "DELETE FROM mo_practice_draws WHERE session_id = ? AND outcome = 'pending'", params: [id] },
    { type: 'run', sql: `UPDATE mo_practice_sessions SET ended_at = ?, spent_seconds = (SELECT COALESCE(SUM(spent_seconds), 0) FROM mo_practice_draws WHERE session_id = ?) WHERE id = ?`, params: [new Date().toISOString(), id, id] },
  ]);
  document.dispatchEvent(new CustomEvent('mo:practice-changed'));
}

function moPracticeOpenRun(api, sessionId, kind) {
  (api || _api).editors.openEditor({
    typeId: 'media-organizer-grid',
    title: kind === 'daily' ? 'Daily Study' : 'Practice',
    icon: 'timer',
    instanceId: `practice:run:${sessionId}`,
  });
}

function moOpenPracticeSetup(api) {
  (api || _api).editors.openEditor({ typeId: 'media-organizer-grid', title: 'Practice Session', icon: 'timer', instanceId: 'practice:setup' });
}

// ── Daily Study ────────────────────────────────────────────────────────────
// One picture per local day, chosen on first open and stored. A day that is
// never started leaves no draw row, so the picture simply stays in the queue.

async function moDailyToday() {
  const day = moPracticeDayKey(new Date());
  let row = await db.get('SELECT * FROM mo_practice_daily WHERE day = ?', [day]);
  if (!row) {
    const cands = await moPracticeCandidates({ kind: 'all' });
    if (!cands.length) return null;
    const pick = moPracticePick(cands, 1)[0];
    await db.run('INSERT OR IGNORE INTO mo_practice_daily (day, photo_id) VALUES (?, ?)', [day, pick.id]);
    row = await db.get('SELECT * FROM mo_practice_daily WHERE day = ?', [day]);
    if (!row) return null;
  }
  const session = row.session_id ? await db.get('SELECT * FROM mo_practice_sessions WHERE id = ?', [row.session_id]) : null;
  return { day, photoId: Number(row.photo_id), session };
}

async function moStartDailyStudy(api, opts) {
  api = api || _api;
  if (!moArtGate(api, () => void moStartDailyStudy(api, opts))) return;
  try {
    const today = await moDailyToday();
    if (!today) { api.window.showInformationMessage('Add some pictures to the library first.'); return; }
    const fresh = !!(opts && opts.fresh);
    if (today.session && !fresh) { moPracticeOpenRun(api, today.session.id, 'daily'); return; }
    const created = await moPracticeCreateSession({
      kind: 'daily',
      pool: { kind: 'photos', ids: [today.photoId], label: 'Daily Study' },
      secondsPer: _practiceCfg.dailyMinutes * 60,
      count: 1,
      options: { mirror: _practiceCfg.mirror, grey: _practiceCfg.greyscale },
    });
    await db.run('UPDATE mo_practice_daily SET session_id = ? WHERE day = ?', [created.id, today.day]);
    moPracticeOpenRun(api, created.id, 'daily');
  } catch (err) {
    api.window.showErrorMessage('Daily Study could not start: ' + (err && err.message));
  }
}

// The Home card. Hidden while the tools are off; refreshes when a run ends.
function moBuildDailyCard(api) {
  const el = moEl('div', 'mo-daily');
  const img = moEl('img', null, { alt: '' });
  const text = moEl('div', 'mo-daily-text');
  const title = moEl('div', 'mo-daily-title', { textContent: 'Daily Study' });
  const sub = moEl('div', 'mo-daily-sub');
  text.appendChild(title); text.appendChild(sub);
  const btn = moEl('button', 'mo-practice-start', { type: 'button', textContent: 'Start' });
  el.appendChild(img); el.appendChild(text); el.appendChild(btn);
  let disposed = false;
  let photoId = 0;
  let done = false;
  img.addEventListener('click', () => { if (photoId) moOpenPhotoDetail(api, photoId); });
  btn.addEventListener('click', () => void moStartDailyStudy(api, { fresh: done }));
  async function refresh() {
    if (disposed) return;
    if (!_artToolsEnabled) { el.style.display = 'none'; return; }
    el.style.display = '';
    try {
      const today = await moDailyToday();
      if (disposed) return;
      if (!today) { sub.textContent = 'Add some pictures to the library first.'; btn.style.display = 'none'; img.style.visibility = 'hidden'; return; }
      btn.style.display = '';
      img.style.visibility = '';
      if (photoId !== today.photoId) { photoId = today.photoId; void moPracticeThumb(img, photoId, api); }
      const s = today.session;
      done = !!(s && s.ended_at);
      if (!s) { sub.textContent = _practiceCfg.dailyMinutes + ' min with one picture, every day'; btn.textContent = 'Start'; }
      else if (!s.ended_at) { sub.textContent = 'In progress'; btn.textContent = 'Continue'; }
      else { sub.textContent = 'Drawn today, ' + moPracticeFormatDuration(s.spent_seconds); btn.textContent = 'Draw Again'; }
    } catch { sub.textContent = ''; }
  }
  document.addEventListener('mo:art-tools-changed', refresh);
  document.addEventListener('mo:practice-changed', refresh);
  void refresh();
  return { el, dispose() { disposed = true; document.removeEventListener('mo:art-tools-changed', refresh); document.removeEventListener('mo:practice-changed', refresh); } };
}

// ── Helpers shared by the practice surfaces ────────────────────────────────

function moPracticeChime() {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    const t0 = ctx.currentTime;
    for (const [freq, dt] of [[880, 0], [1320, 0.18]]) {
      const o = ctx.createOscillator();
      const g = ctx.createGain();
      o.type = 'sine';
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.0001, t0 + dt);
      g.gain.exponentialRampToValueAtTime(0.22, t0 + dt + 0.02);
      g.gain.exponentialRampToValueAtTime(0.0001, t0 + dt + 0.6);
      o.connect(g).connect(ctx.destination);
      o.start(t0 + dt);
      o.stop(t0 + dt + 0.65);
    }
    setTimeout(() => { try { ctx.close(); } catch { /* closed */ } }, 1200);
  } catch { /* no audio */ }
}

async function moPracticeThumb(img, photoId, api) {
  try {
    const cached = _moRecallThumb('photo', photoId);
    let display = cached ? (cached.sourcePath || cached.thumbnailPath) : null;
    if (!display) {
      const r = await resolveThumbnail('photo', photoId, api || _api);
      if (r && (r.path || r.sourcePath)) {
        _moRememberThumb('photo', photoId, { thumbnailPath: r.path || null, sourcePath: r.sourcePath || null, originalPath: r.originalPath || null });
        display = r.sourcePath || r.path;
      }
    }
    if (display) setThumbImgSrc(img, display, {});
  } catch { /* leave the placeholder */ }
}

function moPracticeThumbTile(photoId, caption, api, onClick) {
  const tile = moEl('div', 'mo-practice-thumb');
  const img = moEl('img', null, { alt: '' });
  tile.appendChild(img);
  if (caption != null) tile.appendChild(moEl('span', null, { textContent: caption }));
  void moPracticeThumb(img, photoId, api);
  if (onClick) tile.addEventListener('click', onClick);
  return tile;
}

function moOpenPhotoDetail(api, photoId) {
  (api || _api).editors.openEditor({ typeId: 'media-organizer-grid', title: `photo #${photoId}`, icon: 'image', instanceId: `detail:photo:${photoId}` });
}

// ── Tabs ───────────────────────────────────────────────────────────────────

function renderPracticeTab(container, api, input) {
  const inputId = (input && (input.instanceId || input.id)) || '';
  if (!_artToolsEnabled) {
    moInjectStyles();
    container.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'Turn on drawing and painting tools in Media Organizer settings to use practice.' }));
    return { dispose() { container.innerHTML = ''; } };
  }
  if (inputId.startsWith('practice:run:')) return renderPracticePlayer(container, api, parseInt(inputId.slice('practice:run:'.length), 10) || 0);
  return renderPracticeSetup(container, api);
}

function renderPracticeSetup(container, api) {
  moInjectStyles();
  const root = moEl('div', 'mo-practice-setup');
  container.appendChild(root);
  let disposed = false;
  const disposers = [];

  root.appendChild(moEl('div', 'mo-home-title', { textContent: 'Practice Session' }));
  root.appendChild(moEl('div', 'mo-home-sub', { textContent: 'Timed drawing from a set you choose. Random pictures, a clock, a chime when time is up.' }));

  const s = { pool: { kind: 'all' }, mode: 'count', secondsPer: 120, count: 10, totalMinutes: 30, mirror: _practiceCfg.mirror, grey: _practiceCfg.greyscale, presetId: null };
  const form = moEl('div', 'mo-practice-form');
  root.appendChild(form);
  const row = (label) => {
    const r = moEl('div', 'mo-practice-row');
    r.appendChild(moEl('span', 'mo-practice-label', { textContent: label }));
    form.appendChild(r);
    return r;
  };
  const smallBtn = (label, onClick) => { const b = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: label }); b.addEventListener('click', onClick); return b; };

  // Preset
  const presetRow = row('Preset');
  const presetDrop = moDropdown({ items: [{ value: '', label: 'No Preset' }], selected: '', ariaLabel: 'Preset' });
  disposers.push(() => presetDrop.dispose());
  presetRow.appendChild(presetDrop.el);
  const savePresetBtn = smallBtn('Save Preset', () => void savePreset());
  const deletePresetBtn = smallBtn('Delete Preset', () => void deletePreset());
  presetRow.appendChild(savePresetBtn);
  presetRow.appendChild(deletePresetBtn);
  let presets = [];
  async function loadPresets(selectId) {
    presets = await db.all('SELECT * FROM mo_practice_presets ORDER BY name COLLATE NOCASE ASC');
    if (disposed) return;
    presetDrop.setItems([{ value: '', label: 'No Preset' }, ...presets.map((p) => ({ value: String(p.id), label: p.name }))]);
    presetDrop.setValue(selectId ? String(selectId) : '');
    s.presetId = selectId || null;
    deletePresetBtn.style.display = s.presetId ? '' : 'none';
  }
  presetDrop.onChange = (v) => {
    const p = presets.find((x) => String(x.id) === v);
    s.presetId = p ? p.id : null;
    deletePresetBtn.style.display = p ? '' : 'none';
    if (!p) return;
    try { s.pool = JSON.parse(p.pool_json) || { kind: 'all' }; } catch { s.pool = { kind: 'all' }; }
    s.mode = p.sizing === 'total' ? 'total' : 'count';
    s.secondsPer = p.seconds_per;
    s.count = p.count;
    s.totalMinutes = Math.max(1, Math.round(p.total_seconds / 60));
    try { const o = JSON.parse(p.options_json) || {}; s.mirror = !!o.mirror; s.grey = !!o.grey; } catch { /* keep */ }
    syncControls();
  };
  async function savePreset() {
    if (s.pool.kind === 'photos') { api.window.showInformationMessage('Choose Everything, a tag, an album or a search to save a preset.'); return; }
    const current = presets.find((x) => x.id === s.presetId);
    const name = await api.window.showInputBox({ prompt: 'Preset name', placeHolder: 'Warm-up', value: current ? current.name : '' });
    if (!name || !name.trim() || disposed) return;
    const z = moPracticeSizing(currentSizing());
    await db.run(
      `INSERT INTO mo_practice_presets (name, pool_json, sizing, seconds_per, count, total_seconds, options_json)
       VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(name) DO UPDATE SET pool_json = excluded.pool_json, sizing = excluded.sizing, seconds_per = excluded.seconds_per,
         count = excluded.count, total_seconds = excluded.total_seconds, options_json = excluded.options_json, updated_at = datetime('now')`,
      [name.trim(), JSON.stringify(s.pool), s.mode, z.secondsPer, s.count, s.totalMinutes * 60, JSON.stringify({ mirror: s.mirror, grey: s.grey })]);
    const saved = await db.get('SELECT id FROM mo_practice_presets WHERE name = ?', [name.trim()]);
    await loadPresets(saved ? saved.id : null);
  }
  async function deletePreset() {
    if (!s.presetId) return;
    await db.run('DELETE FROM mo_practice_presets WHERE id = ?', [s.presetId]);
    await loadPresets(null);
  }

  // Pool
  const poolRow = row('Pictures From');
  const kindDrop = moDropdown({ items: [{ value: 'all', label: 'Everything' }, { value: 'tag', label: 'Tag' }, { value: 'album', label: 'Album' }, { value: 'search', label: 'Search' }], selected: 'all', ariaLabel: 'Pool' });
  disposers.push(() => kindDrop.dispose());
  poolRow.appendChild(kindDrop.el);
  const poolDetail = moEl('span', 'mo-practice-pooldetail');
  poolRow.appendChild(poolDetail);
  const poolCount = moEl('span', 'mo-practice-poolcount');
  poolRow.appendChild(poolCount);
  let tags = null; let albums = null; let albumDrop = null;
  let countTimer = null; let countSeq = 0;
  function refreshPoolCount() {
    clearTimeout(countTimer);
    countTimer = setTimeout(async () => {
      const seq = ++countSeq;
      poolCount.textContent = '';
      try {
        const ids = await moPoolPhotoIds(s.pool);
        if (disposed || seq !== countSeq) return;
        poolCount.textContent = ids.length === 1 ? '1 picture' : ids.length + ' pictures';
        startBtn.disabled = ids.length === 0;
      } catch { poolCount.textContent = ''; }
    }, 250);
  }
  function closeSuggest() { const old = document.querySelector('.mo-practice-suggest'); if (old) old.remove(); }
  async function renderPoolDetail() {
    poolDetail.innerHTML = '';
    if (albumDrop) { albumDrop.dispose(); albumDrop = null; }
    const kind = s.pool.kind || 'all';
    if (kind === 'tag') {
      if (!tags) tags = await db.all('SELECT id, name FROM mo_tags ORDER BY name COLLATE NOCASE ASC');
      if (disposed) return;
      const input = moEl('input', 'mo-clip-input mo-clip-input--grow', { type: 'text', placeholder: 'Type a tag', 'aria-label': 'Tag' });
      input.value = s.pool.label || '';
      let items = []; let active = 0;
      const pick = (t) => { closeSuggest(); s.pool = { kind: 'tag', id: t.id, label: t.name }; input.value = t.name; refreshPoolCount(); };
      const open = () => {
        closeSuggest();
        const q = input.value.trim().toLowerCase();
        items = tags.filter((t) => !q || String(t.name).toLowerCase().includes(q)).slice(0, 50);
        if (!items.length) return;
        active = 0;
        const pop = moEl('div', 'mo-tr-suggest mo-practice-suggest');
        pop.setAttribute('role', 'listbox');
        items.forEach((t, i) => {
          const it = moEl('div', `mo-tr-suggest-item${i === active ? ' is-active' : ''}`, { textContent: t.name });
          it.addEventListener('mousedown', (e) => { e.preventDefault(); pick(t); });
          pop.appendChild(it);
        });
        const r = input.getBoundingClientRect();
        pop.style.left = r.left + 'px'; pop.style.top = (r.bottom + 2) + 'px'; pop.style.minWidth = r.width + 'px';
        document.body.appendChild(pop);
      };
      input.addEventListener('input', open);
      input.addEventListener('focus', open);
      input.addEventListener('blur', () => setTimeout(closeSuggest, 120));
      input.addEventListener('keydown', (e) => {
        const pop = document.querySelector('.mo-practice-suggest');
        if (!pop) return;
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
          e.preventDefault();
          active = (active + (e.key === 'ArrowDown' ? 1 : items.length - 1)) % items.length;
          [...pop.children].forEach((c, i) => c.classList.toggle('is-active', i === active));
        } else if (e.key === 'Enter') { e.preventDefault(); if (items[active]) pick(items[active]); }
        else if (e.key === 'Escape') { closeSuggest(); }
      });
      poolDetail.appendChild(input);
    } else if (kind === 'album') {
      if (!albums) albums = await db.all('SELECT id, title FROM mo_albums ORDER BY title COLLATE NOCASE ASC');
      if (disposed) return;
      if (!albums.length) { poolDetail.appendChild(moEl('span', 'mo-practice-poolcount', { textContent: 'No albums yet' })); return; }
      if (!albums.some((a) => a.id === s.pool.id)) s.pool = { kind: 'album', id: albums[0].id, label: albums[0].title };
      albumDrop = moDropdown({ items: albums.map((a) => ({ value: String(a.id), label: a.title })), selected: String(s.pool.id), ariaLabel: 'Album' });
      albumDrop.onChange = (v) => { const a = albums.find((x) => String(x.id) === v); if (a) { s.pool = { kind: 'album', id: a.id, label: a.title }; refreshPoolCount(); } };
      poolDetail.appendChild(albumDrop.el);
    } else if (kind === 'search') {
      const input = moEl('input', 'mo-clip-input mo-clip-input--grow', { type: 'text', placeholder: 'Search the library', 'aria-label': 'Search' });
      input.value = s.pool.query || '';
      input.addEventListener('input', () => { s.pool = { kind: 'search', query: input.value }; refreshPoolCount(); });
      poolDetail.appendChild(input);
    }
  }
  kindDrop.onChange = (v) => {
    if (v === (s.pool.kind || 'all')) return;
    s.pool = v === 'all' ? { kind: 'all' } : { kind: v };
    void renderPoolDetail();
    refreshPoolCount();
  };

  // Sizing
  const sizingRow = row('Size By');
  const chips = moEl('div', 'mo-home-chips');
  const chipEls = {};
  for (const [k, label] of [['count', 'Pictures And Time'], ['total', 'Total Time']]) {
    const b = moEl('button', 'mo-home-chip', { type: 'button', textContent: label });
    b.addEventListener('click', () => { s.mode = k; syncControls(); });
    chipEls[k] = b;
    chips.appendChild(b);
  }
  sizingRow.appendChild(chips);
  const perItems = MO_PRACTICE_PER_OPTIONS.map((v) => ({ value: String(v), label: moPracticeFormatDuration(v) }));
  const totalItems = MO_PRACTICE_TOTAL_OPTIONS.map((v) => ({ value: String(v), label: moPracticeFormatDuration(v * 60) }));
  const countRow = row('Pictures');
  const countInput = moEl('input', 'mo-clip-input mo-clip-input--num', { type: 'number', min: '1', max: '500', step: '1', 'aria-label': 'Pictures' });
  countInput.addEventListener('input', () => { s.count = Math.max(1, Math.min(500, parseInt(countInput.value, 10) || 1)); syncSummary(); });
  countRow.appendChild(countInput);
  const totalRow = row('Total Time');
  const totalDrop = moDropdown({ items: totalItems, selected: String(s.totalMinutes), ariaLabel: 'Total Time' });
  disposers.push(() => totalDrop.dispose());
  totalDrop.onChange = (v) => { s.totalMinutes = parseInt(v, 10) || 30; syncSummary(); };
  totalRow.appendChild(totalDrop.el);
  const perRow = row('Time Per Picture');
  const perDrop = moDropdown({ items: perItems, selected: String(s.secondsPer), ariaLabel: 'Time Per Picture' });
  disposers.push(() => perDrop.dispose());
  perDrop.onChange = (v) => { s.secondsPer = parseInt(v, 10) || 120; syncSummary(); };
  perRow.appendChild(perDrop.el);
  const summary = moEl('div', 'mo-practice-summary');
  form.appendChild(summary);

  // Options
  const optRow = row('Options');
  const check = (label, get, set) => {
    const wrap = moEl('label', 'mo-practice-check');
    const input = moEl('input', 'mo-clip-check', { type: 'checkbox' });
    input.checked = get();
    input.addEventListener('change', () => set(input.checked));
    wrap.appendChild(input);
    wrap.appendChild(moEl('span', null, { textContent: label }));
    wrap._input = input;
    return wrap;
  };
  const mirrorCheck = check('Mirror', () => s.mirror, (v) => { s.mirror = v; });
  const greyCheck = check('Greyscale', () => s.grey, (v) => { s.grey = v; });
  optRow.appendChild(mirrorCheck);
  optRow.appendChild(greyCheck);

  // Start
  const startRow = moEl('div', 'mo-practice-row');
  startRow.appendChild(moEl('span', 'mo-practice-label'));
  const startBtn = moEl('button', 'mo-practice-start', { type: 'button', textContent: 'Start' });
  startBtn.addEventListener('click', () => void start());
  startRow.appendChild(startBtn);
  form.appendChild(startRow);

  function currentSizing() {
    return s.mode === 'total'
      ? { mode: 'total', secondsPer: s.secondsPer, totalSeconds: s.totalMinutes * 60 }
      : { mode: 'count', secondsPer: s.secondsPer, count: s.count };
  }
  function syncSummary() {
    summary.textContent = moPracticeSizingText(currentSizing());
  }
  function syncControls() {
    for (const k of Object.keys(chipEls)) chipEls[k].classList.toggle('active', s.mode === k);
    countRow.style.display = s.mode === 'count' ? '' : 'none';
    totalRow.style.display = s.mode === 'total' ? '' : 'none';
    countInput.value = String(s.count);
    totalDrop.setValue(String(MO_PRACTICE_TOTAL_OPTIONS.includes(s.totalMinutes) ? s.totalMinutes : 30));
    perDrop.setValue(String(MO_PRACTICE_PER_OPTIONS.includes(s.secondsPer) ? s.secondsPer : 120));
    mirrorCheck._input.checked = s.mirror;
    greyCheck._input.checked = s.grey;
    kindDrop.setValue(s.pool.kind === 'photos' ? 'all' : (s.pool.kind || 'all'));
    void renderPoolDetail();
    refreshPoolCount();
    syncSummary();
  }
  async function start() {
    const z = moPracticeSizing(currentSizing());
    if (z.count < 1) { api.window.showInformationMessage('Choose at least one picture.'); return; }
    startBtn.disabled = true;
    try {
      const created = await moPracticeCreateSession({
        kind: 'practice', presetId: s.presetId, pool: s.pool, secondsPer: z.secondsPer, count: z.count,
        options: { mirror: s.mirror, grey: s.grey, mode: s.mode, totalSeconds: s.totalMinutes * 60 },
      });
      await moSetSetting('practice_setup', JSON.stringify({ pool: s.pool, mode: s.mode, secondsPer: s.secondsPer, count: s.count, totalMinutes: s.totalMinutes, mirror: s.mirror, grey: s.grey, presetId: s.presetId }));
      if (created.shortfall > 0) {
        api.window.showInformationMessage(`Only ${created.count === 1 ? '1 picture' : created.count + ' pictures'} in this pool. The run uses all of them.`);
      }
      moPracticeOpenRun(api, created.id, 'practice');
    } catch (err) {
      api.window.showInformationMessage((err && err.message) || 'The run could not start.');
    } finally {
      if (!disposed) startBtn.disabled = false;
    }
  }

  // Below the form: what has waited longest, and recent runs.
  const neglectedSec = moEl('div', 'mo-practice-section');
  neglectedSec.appendChild(moEl('div', 'mo-practice-section-title', { textContent: 'Not Drawn Lately' }));
  const neglectedBody = moEl('div', 'mo-practice-thumbs');
  neglectedSec.appendChild(neglectedBody);
  root.appendChild(neglectedSec);
  const recentSec = moEl('div', 'mo-practice-section');
  recentSec.appendChild(moEl('div', 'mo-practice-section-title', { textContent: 'Recent Sessions' }));
  const recentBody = moEl('div', 'mo-practice-list');
  recentSec.appendChild(recentBody);
  root.appendChild(recentSec);
  async function loadBelow() {
    try {
      const cands = await moPracticeCandidates({ kind: 'all' });
      if (disposed) return;
      neglectedBody.innerHTML = '';
      const list = moPracticeNeglected(cands, 12);
      if (!list.length) neglectedBody.appendChild(moEl('div', 'mo-practice-poolcount', { textContent: 'No pictures in the library yet.' }));
      for (const c of list) {
        neglectedBody.appendChild(moPracticeThumbTile(c.id, c.lastDrawnAt == null ? 'Not drawn yet' : moPracticeDate(new Date(c.lastDrawnAt).toISOString()), api, () => moOpenPhotoDetail(api, c.id)));
      }
      const sessions = await db.all(
        `SELECT s.*, (SELECT COUNT(*) FROM mo_practice_draws d WHERE d.session_id = s.id AND d.outcome != 'pending') AS shown
         FROM mo_practice_sessions s ORDER BY s.started_at DESC LIMIT 8`);
      if (disposed) return;
      recentBody.innerHTML = '';
      if (!sessions.length) recentBody.appendChild(moEl('div', 'mo-practice-poolcount', { textContent: 'No sessions yet.' }));
      for (const sess of sessions) {
        let pool = { kind: 'all' };
        try { pool = JSON.parse(sess.pool_json) || pool; } catch { /* default */ }
        const r = moEl('div', 'mo-practice-list-row');
        r.appendChild(moEl('span', null, { textContent: moPracticeDate(sess.started_at) }));
        r.appendChild(moEl('span', 'mo-practice-dim', { textContent: sess.kind === 'daily' ? 'Daily Study' : moPoolLabel(pool) }));
        r.appendChild(moEl('span', 'mo-practice-dim', { textContent: (sess.shown === 1 ? '1 picture' : sess.shown + ' pictures') + (sess.ended_at ? ', ' + moPracticeFormatDuration(sess.spent_seconds) : ', in progress') }));
        r.addEventListener('click', () => moPracticeOpenRun(api, sess.id, sess.kind));
        recentBody.appendChild(r);
      }
    } catch { /* leave empty */ }
  }
  document.addEventListener('mo:practice-changed', loadBelow);

  (async () => {
    try {
      const saved = JSON.parse((await moGetSetting('practice_setup', '')) || 'null');
      if (saved && typeof saved === 'object') {
        if (saved.pool && saved.pool.kind !== 'photos') s.pool = saved.pool;
        if (saved.mode === 'total' || saved.mode === 'count') s.mode = saved.mode;
        if (Number(saved.secondsPer) > 0) s.secondsPer = Number(saved.secondsPer);
        if (Number(saved.count) > 0) s.count = Number(saved.count);
        if (Number(saved.totalMinutes) > 0) s.totalMinutes = Number(saved.totalMinutes);
        s.mirror = !!saved.mirror; s.grey = !!saved.grey;
        s.presetId = saved.presetId || null;
      }
    } catch { /* defaults */ }
    if (disposed) return;
    await loadPresets(s.presetId);
    syncControls();
    void loadBelow();
  })();

  return {
    dispose() {
      disposed = true;
      closeSuggest();
      clearTimeout(countTimer);
      document.removeEventListener('mo:practice-changed', loadBelow);
      for (const d of disposers) { try { d(); } catch { /* gone */ } }
      if (albumDrop) albumDrop.dispose();
      container.innerHTML = '';
    },
  };
}

function renderPracticePlayer(container, api, sessionId) {
  moInjectStyles();
  const root = moEl('div', 'mo-practice');
  root.tabIndex = 0;
  container.appendChild(root);
  let disposed = false;
  let timer = null;
  let idleTimer = null;
  let noticeTimer = null;
  const state = { session: null, draws: [], idx: -1, running: false, remainingMs: 0, lastTick: 0, mirror: _practiceCfg.mirror, grey: _practiceCfg.greyscale };

  const stage = moEl('div', 'mo-practice-stage');
  const img = moEl('img', 'mo-practice-img', { alt: '' });
  stage.appendChild(img);
  const missing = moEl('div', 'mo-practice-empty mo-hidden', { textContent: 'This picture is not on disk right now.' });
  stage.appendChild(missing);
  root.appendChild(stage);
  const hud = moEl('div', 'mo-practice-hud');
  const clock = moEl('div', 'mo-practice-clock', { textContent: '0:00' });
  const counter = moEl('div', 'mo-practice-counter');
  hud.appendChild(clock); hud.appendChild(counter);
  root.appendChild(hud);
  const notice = moEl('div', 'mo-practice-notice', { textContent: 'Time Is Up' });
  root.appendChild(notice);
  const controls = moEl('div', 'mo-practice-controls');
  const btn = (icon, title, fn) => {
    const b = moEl('button', 'mo-practice-btn', { type: 'button', title, 'aria-label': title, innerHTML: moIcon(icon, 16) });
    b.addEventListener('click', (e) => { e.stopPropagation(); fn(); });
    return b;
  };
  const prevBtn = btn('skip-back', 'Previous', () => void goTo(state.idx - 1));
  const pauseBtn = btn('pause', 'Pause', () => togglePause());
  const nextBtn = btn('skip-forward', 'Skip', () => void skip());
  const stopBtn = btn('square', 'Stop', () => void finish());
  const mirrorBtn = btn('flip-horizontal', 'Mirror', () => { state.mirror = !state.mirror; applyLook(); });
  const greyBtn = btn('contrast', 'Greyscale', () => { state.grey = !state.grey; applyLook(); });
  for (const b of [prevBtn, pauseBtn, nextBtn, stopBtn]) controls.appendChild(b);
  controls.appendChild(moEl('span', 'mo-practice-sep'));
  controls.appendChild(mirrorBtn);
  controls.appendChild(greyBtn);
  root.appendChild(controls);
  const strip = moEl('div', 'mo-practice-strip');
  root.appendChild(strip);
  const end = moEl('div', 'mo-practice-end mo-hidden');
  root.appendChild(end);

  function applyLook() {
    img.classList.toggle('is-mirror', state.mirror);
    img.classList.toggle('is-grey', state.grey);
    mirrorBtn.classList.toggle('is-on', state.mirror);
    greyBtn.classList.toggle('is-on', state.grey);
  }
  function wake() {
    root.classList.remove('is-idle');
    clearTimeout(idleTimer);
    idleTimer = setTimeout(() => { if (!disposed && state.running) root.classList.add('is-idle'); }, 2500);
  }
  root.addEventListener('mousemove', wake);
  root.addEventListener('click', wake);
  root.addEventListener('keydown', (e) => {
    if (state.idx < 0 || !end.classList.contains('mo-hidden')) return;
    if (e.key === ' ') { e.preventDefault(); togglePause(); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); void skip(); }
    else if (e.key === 'ArrowLeft') { e.preventDefault(); void goTo(state.idx - 1); }
    else if (e.key === 'm' || e.key === 'M') { state.mirror = !state.mirror; applyLook(); }
    else if (e.key === 'g' || e.key === 'G') { state.grey = !state.grey; applyLook(); }
    wake();
  });

  function snapshot(d) { return { spent_seconds: Math.round((d._spentMs || 0) / 1000), outcome: d.outcome, drawn_at: d.drawn_at }; }
  function flushSpent() {
    if (!state.running) return;
    const now = performance.now();
    const dt = Math.max(0, now - state.lastTick);
    state.lastTick = now;
    const d = state.draws[state.idx];
    if (!d) return;
    d._spentMs = (d._spentMs || 0) + dt;
    state.remainingMs -= dt;
  }
  function renderClock() {
    clock.textContent = moPracticeClock(state.remainingMs / 1000);
    hud.classList.toggle('is-low', state.remainingMs > 0 && state.remainingMs <= 10000);
  }
  function renderCounter() { counter.textContent = (state.idx + 1) + ' / ' + state.draws.length; }
  function markStrip() {
    [...strip.children].forEach((c, i) => {
      c.classList.toggle('is-current', i === state.idx);
      c.classList.toggle('is-done', i !== state.idx && state.draws[i] && state.draws[i].outcome !== 'pending');
    });
  }
  function buildStrip() {
    strip.innerHTML = '';
    state.draws.forEach((d, i) => {
      const it = moEl('div', 'mo-practice-strip-item');
      const t = moEl('img', null, { alt: '' });
      it.appendChild(t);
      void moPracticeThumb(t, d.photo_id, api);
      it.addEventListener('click', (e) => { e.stopPropagation(); void goTo(i); });
      strip.appendChild(it);
    });
  }
  function showNotice() {
    notice.classList.add('is-on');
    clearTimeout(noticeTimer);
    noticeTimer = setTimeout(() => notice.classList.remove('is-on'), 2500);
  }
  let showSeq = 0;
  async function showPhoto(photoId) {
    const seq = ++showSeq;
    const path = await moResolveItemPath({ type: 'photo', id: photoId });
    const url = path ? await localFileToUrl(path) : null;
    if (disposed || seq !== showSeq) return;
    missing.classList.toggle('mo-hidden', !!url);
    img.style.visibility = url ? '' : 'hidden';
    if (url) img.src = url;
  }
  function preload(i) {
    const d = state.draws[i];
    if (!d) return;
    moResolveItemPath({ type: 'photo', id: d.photo_id }).then((p) => (p ? localFileToUrl(p) : null)).catch(() => {});
  }
  async function leaveCurrent() {
    const cur = state.draws[state.idx];
    if (!cur) return;
    flushSpent();
    if (cur.outcome === 'pending') cur.outcome = (cur._spentMs || 0) >= cur.planned_seconds * 1000 ? 'done' : 'skipped';
    await moPracticeUpdateDraw(cur.id, snapshot(cur));
  }
  async function goTo(i) {
    if (i < 0 || i >= state.draws.length || disposed) return;
    if (state.idx >= 0) await leaveCurrent();
    if (disposed) return;
    state.idx = i;
    const d = state.draws[i];
    if (!d.drawn_at) d.drawn_at = new Date().toISOString();
    if (d._spentMs == null) d._spentMs = (Number(d.spent_seconds) || 0) * 1000;
    state.remainingMs = d.planned_seconds * 1000;
    state.running = true;
    state.lastTick = performance.now();
    pauseBtn.innerHTML = moIcon('pause', 16); pauseBtn.title = 'Pause'; pauseBtn.setAttribute('aria-label', 'Pause');
    renderClock(); renderCounter(); markStrip(); wake();
    await showPhoto(d.photo_id);
    preload(i + 1);
    await moPracticeUpdateDraw(d.id, snapshot(d));
  }
  function togglePause() {
    if (state.idx < 0) return;
    flushSpent();
    state.running = !state.running;
    state.lastTick = performance.now();
    const label = state.running ? 'Pause' : 'Resume';
    pauseBtn.innerHTML = moIcon(state.running ? 'pause' : 'play', 16);
    pauseBtn.title = label; pauseBtn.setAttribute('aria-label', label);
    wake();
  }
  async function skip() {
    if (state.idx < state.draws.length - 1) await goTo(state.idx + 1);
    else await finish();
  }
  async function timeUp() {
    state.running = false;
    const d = state.draws[state.idx];
    if (d) d.outcome = 'done';
    if (_practiceCfg.chime) moPracticeChime();
    showNotice();
    if (state.idx < state.draws.length - 1) await goTo(state.idx + 1);
    else await finish();
  }
  function tick() {
    if (disposed || !state.running) return;
    flushSpent();
    renderClock();
    if (state.remainingMs <= 0) void timeUp();
  }
  let finishing = false;
  async function finish() {
    if (finishing || disposed) return;
    finishing = true;
    try {
      if (state.idx >= 0) await leaveCurrent();
      state.running = false;
      clearInterval(timer); timer = null;
      await moPracticeEndSession(sessionId);
      const data = await moPracticeLoadSession(sessionId);
      if (disposed || !data) return;
      state.session = data.session; state.draws = data.draws;
      showEnd();
    } finally { finishing = false; }
  }
  function showEnd() {
    state.running = false;
    root.classList.remove('is-idle');
    for (const el of [stage, hud, controls, strip, notice]) el.classList.add('mo-hidden');
    end.classList.remove('mo-hidden');
    end.innerHTML = '';
    const daily = state.session.kind === 'daily';
    const sum = moPracticeSummary(state.draws);
    end.appendChild(moEl('div', 'mo-practice-end-title', { textContent: daily ? 'Daily Study Complete' : 'Session Complete' }));
    const parts = [sum.shown === 1 ? '1 picture' : sum.shown + ' pictures', moPracticeFormatDuration(sum.spentSeconds)];
    if (!daily) parts.push(moPoolLabel(state.session.pool));
    parts.push(moPracticeDate(state.session.started_at));
    end.appendChild(moEl('div', 'mo-practice-end-sub', { textContent: parts.join(' · ') }));
    const items = state.draws.map((d) => ({ type: 'photo', id: d.photo_id }));
    const endStrip = moEl('div', 'mo-practice-end-strip');
    state.draws.forEach((d, i) => {
      const it = moEl('div', 'mo-practice-end-item');
      const t = moEl('img', null, { alt: '' });
      it.appendChild(t);
      void moPracticeThumb(t, d.photo_id, api);
      it.appendChild(moEl('span', null, { textContent: moPracticeFormatDuration(d.spent_seconds) + (d.outcome === 'skipped' ? ', skipped' : '') }));
      it.addEventListener('click', () => openLightbox(items, i, moResolveItemPath));
      endStrip.appendChild(it);
    });
    end.appendChild(endStrip);
    const actions = moEl('div', 'mo-practice-end-actions');
    const again = moEl('button', 'mo-practice-start', { type: 'button', textContent: daily ? 'Draw Again' : 'Practice Again' });
    again.addEventListener('click', async () => {
      again.disabled = true;
      try {
        if (daily) { await moStartDailyStudy(api, { fresh: true }); return; }
        const o = state.session.options || {};
        const created = await moPracticeCreateSession({
          kind: 'practice', presetId: state.session.preset_id, pool: state.session.pool, secondsPer: state.session.seconds_per,
          count: o.count || state.draws.length || 1, options: o,
        });
        moPracticeOpenRun(api, created.id, 'practice');
      } catch (err) {
        api.window.showInformationMessage((err && err.message) || 'The run could not start.');
      } finally { again.disabled = false; }
    });
    actions.appendChild(again);
    if (!daily) {
      const setup = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Open Practice Setup' });
      setup.addEventListener('click', () => moOpenPracticeSetup(api));
      actions.appendChild(setup);
    }
    end.appendChild(actions);
  }

  (async () => {
    try {
      const data = await moPracticeLoadSession(sessionId);
      if (disposed) return;
      if (!data || !data.draws.length) {
        root.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'This practice run is no longer available.' }));
        for (const el of [stage, hud, controls, strip]) el.classList.add('mo-hidden');
        return;
      }
      state.session = data.session; state.draws = data.draws;
      const o = data.session.options || {};
      if (typeof o.mirror === 'boolean') state.mirror = o.mirror;
      if (typeof o.grey === 'boolean') state.grey = o.grey;
      applyLook();
      if (data.session.ended_at) { showEnd(); return; }
      buildStrip();
      timer = setInterval(tick, 250);
      const first = state.draws.findIndex((d) => d.outcome === 'pending');
      await goTo(first >= 0 ? first : 0);
      root.focus();
    } catch (err) {
      if (!disposed) root.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'The practice run could not load: ' + (err && err.message) }));
    }
  })();

  return {
    dispose() {
      disposed = true;
      clearInterval(timer); clearTimeout(idleTimer); clearTimeout(noticeTimer);
      const cur = state.draws[state.idx];
      if (cur && state.session && !state.session.ended_at) {
        flushSpent();
        state.running = false;
        moPracticeUpdateDraw(cur.id, snapshot(cur)).catch(() => {});
      }
      container.innerHTML = '';
    },
  };
}

// Detail view: when this picture was drawn, oldest to newest (slice 4).
function buildPracticeHistoryStrip(ctx, api) {
  const id = ctx.entity ? ctx.entity.id : ctx.id;
  const wrap = moEl('div', 'mo-similar');
  const head = moEl('div', 'mo-practice-history-head');
  head.appendChild(moEl('div', 'mo-similar-title', { textContent: 'Drawing and Painting' }));
  const actions = moEl('div', 'mo-practice-history-actions');
  const addBtn = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Add To Plan' });
  addBtn.addEventListener('click', () => void moPlanPickAndAdd(api, ctx.type === 'video' ? 'video' : 'photo', id));
  if (ctx.type === 'video') {
    actions.appendChild(addBtn); head.appendChild(actions); wrap.appendChild(head);
    return wrap;
  }
  const planBtn = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Plan Painting' });
  planBtn.addEventListener('click', () => void moPlanCreate(api, id));
  const drawBtn = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Draw This' });
  drawBtn.addEventListener('click', async () => {
    drawBtn.disabled = true;
    try {
      const created = await moPracticeCreateSession({
        kind: 'practice', pool: { kind: 'photos', ids: [id], label: '1 picture' }, secondsPer: _practiceCfg.dailyMinutes * 60, count: 1,
        options: { mirror: _practiceCfg.mirror, grey: _practiceCfg.greyscale },
      });
      moPracticeOpenRun(api, created.id, 'practice');
    } catch (err) {
      api.window.showInformationMessage((err && err.message) || 'The run could not start.');
    } finally { drawBtn.disabled = false; }
  });
  actions.appendChild(drawBtn); actions.appendChild(planBtn); actions.appendChild(addBtn);
  head.appendChild(actions);
  wrap.appendChild(head);
  const body = moEl('div', 'mo-practice-history');
  wrap.appendChild(body);
  (async () => {
    try {
      const rows = await db.all(`SELECT drawn_at, spent_seconds, outcome FROM mo_practice_draws WHERE photo_id = ? AND outcome != 'pending' AND drawn_at IS NOT NULL ORDER BY drawn_at ASC`, [id]);
      if (!rows.length) { body.appendChild(moEl('div', 'mo-practice-history-row mo-practice-dim', { textContent: 'Not drawn yet' })); return; }
      for (const r of rows) {
        const row = moEl('div', 'mo-practice-history-row');
        row.appendChild(moEl('span', null, { textContent: moPracticeDate(r.drawn_at) }));
        row.appendChild(moEl('span', 'mo-practice-dim', { textContent: moPracticeFormatDuration(r.spent_seconds) + (r.outcome === 'skipped' ? ', skipped' : '') }));
        body.appendChild(row);
      }
    } catch { /* leave empty */ }
  })();
  return wrap;
}

// ═══════════════════════════════════════════════════════════════════════════
// Section 45: Painting plans (M104 Part B, docs/Parallx_Milestone_104.md)
//
// The step before the canvas. A plan is one painting: a source photo, the
// canvas size in inches, and variations, each a recipe of non-destructive
// adjustments (crop locked to the canvas, light, colour, values, overlays,
// palette). The original file is never touched; the recipe renders live on
// the GPU and the export renders the same recipe beside the original, as a
// photo of its own in the library. Behind mediaOrganizer.enableArtTools (D7).
// ═══════════════════════════════════════════════════════════════════════════

// @mo-plan-pure-begin — pure plan math (extracted verbatim by tests/unit/moPlan.test.ts)

const MO_PLAN_CANVAS_PRESETS = [[8, 10], [9, 12], [11, 14], [12, 16], [16, 20], [18, 24], [24, 30], [24, 36], [30, 40]];

function moPlanDefaultRecipe() {
  return {
    crop: { x: 0, y: 0, w: 1, h: 1 }, rotate: 0, flipH: false, flipV: false,
    exposure: 0, contrast: 0, highlights: 0, shadows: 0, warmth: 0, tint: 0, hue: 0, saturation: 0,
    grey: false, levels: 0, notan: 0, blur: 0,
    overlays: { thirds: false, golden: false, diagonals: false, grid: false, gridInches: 1 },
    palette: { count: 8, swatches: [], apply: false },
  };
}

// Fill in anything a stored recipe lacks, so old rows keep working.
function moPlanNormalizeRecipe(r) {
  const d = moPlanDefaultRecipe();
  const o = r && typeof r === 'object' ? r : {};
  const out = Object.assign({}, d, o);
  out.crop = Object.assign({}, d.crop, o.crop || {});
  out.overlays = Object.assign({}, d.overlays, o.overlays || {});
  out.palette = Object.assign({}, d.palette, o.palette || {});
  out.palette.swatches = Array.isArray(out.palette.swatches) ? out.palette.swatches.slice(0, 16) : [];
  out.rotate = ((Math.round(Number(out.rotate) || 0) % 4) + 4) % 4;
  return out;
}

// Image size after rotation (quarter turns swap the sides).
function moPlanRotatedSize(w, h, rotate) {
  const r = ((Math.round(Number(rotate) || 0) % 4) + 4) % 4;
  return r % 2 === 1 ? { w: h, h: w } : { w, h };
}

// The largest centred crop of an image (rotated size w×h) with the canvas
// proportions, in normalized units of that rotated image.
function moPlanFitCrop(w, h, aspect) {
  const a = Number(aspect) > 0 ? Number(aspect) : 1;
  if (!(w > 0) || !(h > 0)) return { x: 0, y: 0, w: 1, h: 1 };
  const imgAspect = w / h;
  if (imgAspect > a) {
    const cw = (a * h) / w;
    return { x: (1 - cw) / 2, y: 0, w: cw, h: 1 };
  }
  const ch = (w / a) / h;
  return { x: 0, y: (1 - ch) / 2, w: 1, h: ch };
}

// Keep a crop inside the image at the canvas proportions. Shrinks first,
// then slides. w,h are the rotated image pixel size.
function moPlanClampCrop(crop, w, h, aspect) {
  const a = Number(aspect) > 0 ? Number(aspect) : 1;
  const fit = moPlanFitCrop(w, h, a);
  let cw = Math.min(Math.max(Number(crop.w) || fit.w, 0.02), fit.w);
  let ch = (cw * w) / (a * h);
  if (ch > 1) { ch = 1; cw = (a * h) / w; }
  let x = Number(crop.x) || 0;
  let y = Number(crop.y) || 0;
  x = Math.min(Math.max(x, 0), 1 - cw);
  y = Math.min(Math.max(y, 0), 1 - ch);
  return { x, y, w: cw, h: ch };
}

// The transfer grid: line positions (0..1) across a crop that stands for a
// canvas of canvasW×canvasH inches, one line every `inches`. Also the
// labels so the sheet can be read at the easel.
function moPlanGridLines(canvasW, canvasH, inches) {
  const step = Number(inches) > 0 ? Number(inches) : 1;
  const cw = Number(canvasW) > 0 ? Number(canvasW) : 1;
  const ch = Number(canvasH) > 0 ? Number(canvasH) : 1;
  const xs = []; const ys = [];
  for (let v = step; v < cw - 1e-9; v += step) xs.push(v / cw);
  for (let v = step; v < ch - 1e-9; v += step) ys.push(v / ch);
  return { xs, ys, cols: Math.ceil(cw / step), rows: Math.ceil(ch / step) };
}

// k-means over [r,g,b] samples (0..255). Deterministic for a given rng.
function moPlanKMeans(samples, k, iterations, rng) {
  const rand = typeof rng === 'function' ? rng : Math.random;
  const n = samples.length;
  const kk = Math.max(1, Math.min(16, Math.floor(Number(k) || 1)));
  if (!n) return [];
  const centres = [];
  const used = new Set();
  while (centres.length < Math.min(kk, n)) {
    const i = Math.floor(rand() * n);
    if (used.has(i)) continue;
    used.add(i);
    centres.push(samples[i].slice(0, 3));
  }
  const assign = new Int32Array(n);
  for (let it = 0; it < Math.max(1, iterations || 8); it++) {
    for (let i = 0; i < n; i++) {
      const s = samples[i];
      let best = 0; let bd = Infinity;
      for (let c = 0; c < centres.length; c++) {
        const d = (s[0] - centres[c][0]) ** 2 + (s[1] - centres[c][1]) ** 2 + (s[2] - centres[c][2]) ** 2;
        if (d < bd) { bd = d; best = c; }
      }
      assign[i] = best;
    }
    const sums = centres.map(() => [0, 0, 0, 0]);
    for (let i = 0; i < n; i++) { const a = sums[assign[i]]; const s = samples[i]; a[0] += s[0]; a[1] += s[1]; a[2] += s[2]; a[3]++; }
    for (let c = 0; c < centres.length; c++) if (sums[c][3]) centres[c] = [sums[c][0] / sums[c][3], sums[c][1] / sums[c][3], sums[c][2] / sums[c][3]];
  }
  const counts = centres.map(() => 0);
  for (let i = 0; i < n; i++) counts[assign[i]]++;
  return centres.map((c, i) => ({ rgb: c.map((v) => Math.round(v)), share: counts[i] / n }))
    .sort((a, b) => b.share - a.share);
}

function moPlanHex(rgb) {
  return '#' + rgb.map((v) => Math.max(0, Math.min(255, Math.round(v))).toString(16).padStart(2, '0')).join('');
}

// "<name>_plan_1.jpg" beside the original.
function moPlanOutputName(basename, n) {
  const dot = basename.lastIndexOf('.');
  const stem = dot > 0 ? basename.slice(0, dot) : basename;
  return `${stem}_plan_${n}.jpg`;
}
// @mo-plan-pure-end

// ── Data ───────────────────────────────────────────────────────────────────

async function moPlanLoad(planId) {
  const plan = await db.get('SELECT * FROM mo_plans WHERE id = ?', [planId]);
  if (!plan) return null;
  const variants = await db.all('SELECT * FROM mo_plan_variants WHERE plan_id = ? ORDER BY position ASC, id ASC', [planId]);
  for (const v of variants) { try { v.recipe = moPlanNormalizeRecipe(JSON.parse(v.recipe_json)); } catch { v.recipe = moPlanDefaultRecipe(); } }
  const media = await db.all('SELECT * FROM mo_plan_media WHERE plan_id = ? ORDER BY position ASC, id ASC', [planId]);
  return { plan, variants, media };
}

async function moPlanCreate(api, photoId) {
  api = api || _api;
  if (!moArtGate(api)) return null;
  const photo = await PhotoQueries.findById(photoId);
  if (!photo) { api.window.showInformationMessage('That picture is no longer in the library.'); return null; }
  const files = await PhotoQueries.loadFiles(photoId);
  const primary = files.find((f) => f.isPrimary) || files[0];
  const title = (photo.title && String(photo.title).trim()) || (primary ? String(primary.basename).replace(/\.[^.]+$/, '') : 'Painting');
  const now = new Date().toISOString();
  const res = await db.run('INSERT INTO mo_plans (title, photo_id, canvas_w, canvas_h, created_at, updated_at) VALUES (?, ?, 16, 20, ?, ?)', [title, photoId, now, now]);
  const planId = res.lastInsertRowid;
  const v = await db.run('INSERT INTO mo_plan_variants (plan_id, name, recipe_json, position) VALUES (?, ?, ?, 0)', [planId, 'Variation 1', JSON.stringify(moPlanDefaultRecipe())]);
  await db.run('UPDATE mo_plans SET variant_id = ? WHERE id = ?', [v.lastInsertRowid, planId]);
  document.dispatchEvent(new CustomEvent('mo:plans-changed'));
  moOpenPlan(api, planId);
  return planId;
}

async function moPlanAddMedia(api, planId, kind, itemId) {
  const exists = await db.get('SELECT id FROM mo_plan_media WHERE plan_id = ? AND kind = ? AND item_id = ?', [planId, kind, itemId]);
  if (exists) return;
  const pos = await db.get('SELECT COALESCE(MAX(position), -1) + 1 AS p FROM mo_plan_media WHERE plan_id = ?', [planId]);
  await db.run('INSERT INTO mo_plan_media (plan_id, kind, item_id, role, position, created_at) VALUES (?, ?, ?, ?, ?, ?)', [planId, kind, itemId, 'process', pos ? pos.p : 0, new Date().toISOString()]);
  await db.run("UPDATE mo_plans SET updated_at = ? WHERE id = ?", [new Date().toISOString(), planId]);
  document.dispatchEvent(new CustomEvent('mo:plans-changed'));
}

// "Add To Plan" from a photo or clip: pick the plan, attach to its process shelf.
async function moPlanPickAndAdd(api, kind, itemId) {
  api = api || _api;
  if (!moArtGate(api)) return;
  const plans = await db.all('SELECT id, title FROM mo_plans ORDER BY updated_at DESC');
  if (!plans.length) { api.window.showInformationMessage('No painting plans yet. Open a photo and choose Plan Painting.'); return; }
  const picked = await api.window.showQuickPick(plans.map((p) => ({ label: p.title, id: p.id })), { placeHolder: 'Add to which plan?' });
  const chosen = picked && (picked.id != null ? picked : plans.find((p) => p.title === picked.label || p.title === picked));
  if (!chosen) return;
  await moPlanAddMedia(api, chosen.id, kind, itemId);
  api.window.showInformationMessage(`Added to "${chosen.title}".`);
}

function moOpenPlansList(api) {
  (api || _api).editors.openEditor({ typeId: 'media-organizer-grid', title: 'Painting Plans', icon: 'palette', instanceId: 'plans:list' });
}
function moOpenPlan(api, planId) {
  (api || _api).editors.openEditor({ typeId: 'media-organizer-grid', title: 'Plan', icon: 'palette', instanceId: `plans:edit:${planId}` });
}

function renderPlansTab(container, api, input) {
  const inputId = (input && (input.instanceId || input.id)) || '';
  if (!_artToolsEnabled) {
    moInjectStyles();
    container.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'Turn on drawing and painting tools in Media Organizer settings to use painting plans.' }));
    return { dispose() { container.innerHTML = ''; } };
  }
  if (inputId.startsWith('plans:edit:')) return renderPlanEditor(container, api, parseInt(inputId.slice('plans:edit:'.length), 10) || 0);
  return renderPlansList(container, api);
}

// ── The list ───────────────────────────────────────────────────────────────

function renderPlansList(container, api) {
  moInjectStyles();
  const root = moEl('div', 'mo-practice-setup');
  container.appendChild(root);
  let disposed = false;
  root.appendChild(moEl('div', 'mo-home-title', { textContent: 'Painting Plans' }));
  root.appendChild(moEl('div', 'mo-home-sub', { textContent: 'Work the design out on the photo before the canvas. Open a photo and choose Plan Painting to start one.' }));
  const grid = moEl('div', 'mo-plans-grid');
  root.appendChild(grid);
  async function load() {
    try {
      const plans = await db.all('SELECT * FROM mo_plans ORDER BY updated_at DESC');
      if (disposed) return;
      grid.innerHTML = '';
      if (!plans.length) { grid.appendChild(moEl('div', 'mo-practice-poolcount', { textContent: 'No plans yet.' })); return; }
      for (const p of plans) {
        const card = moEl('div', 'mo-plans-card');
        const img = moEl('img', null, { alt: '' });
        card.appendChild(img);
        void moPracticeThumb(img, p.photo_id, api);
        card.appendChild(moEl('div', 'mo-plans-card-title', { textContent: p.title }));
        card.appendChild(moEl('div', 'mo-practice-dim', { textContent: `${p.canvas_w} × ${p.canvas_h} in · ${moPracticeDate(p.updated_at)}` }));
        card.addEventListener('click', () => moOpenPlan(api, p.id));
        grid.appendChild(card);
      }
    } catch { /* leave empty */ }
  }
  document.addEventListener('mo:plans-changed', load);
  void load();
  return { dispose() { disposed = true; document.removeEventListener('mo:plans-changed', load); container.innerHTML = ''; } };
}

// ── The renderer ───────────────────────────────────────────────────────────
// One WebGL program applies a whole recipe, for Painting Plans and for the
// image editor (docs/IMAGE_EDITOR.md). Where a pixel comes from is two maps:
// canvas to output (zoom and pan, or one tile of a save) and output to source
// (crop, straighten, quarter turns, flips). Controls that look at a pixel's
// neighbourhood (texture, clarity, dehaze) read two blurred copies of the
// source, made once per source by halving it and blurring the small copy.
// Every control is skipped when it is at rest, so a recipe that leaves it
// alone draws exactly what it drew before the control existed.

const MO_PLAN_VS = `
attribute vec2 a_pos; varying vec2 v_uv;
void main() { v_uv = vec2(a_pos.x * 0.5 + 0.5, 0.5 - a_pos.y * 0.5); gl_Position = vec4(a_pos, 0.0, 1.0); }`;
// Texture space in, texture space out: for passes that write a texture.
const MO_ENGINE_COPY_VS = `
attribute vec2 a_pos; varying vec2 v_uv;
void main() { v_uv = a_pos * 0.5 + 0.5; gl_Position = vec4(a_pos, 0.0, 1.0); }`;
// Nine taps of a gaussian along u_step; u_step of zero is a plain copy.
const MO_ENGINE_BLUR_FS = `
precision highp float;
varying vec2 v_uv;
uniform sampler2D u_img;
uniform vec2 u_step;
void main() {
  vec4 c = texture2D(u_img, v_uv) * 0.227027;
  c += (texture2D(u_img, v_uv + u_step * 1.384615) + texture2D(u_img, v_uv - u_step * 1.384615)) * 0.316216;
  c += (texture2D(u_img, v_uv + u_step * 3.230769) + texture2D(u_img, v_uv - u_step * 3.230769)) * 0.070270;
  gl_FragColor = c;
}`;
const MO_ENGINE_FS = `
precision highp float;
varying vec2 v_uv;
uniform sampler2D u_img;
uniform sampler2D u_blurS;
uniform sampler2D u_blurL;
uniform sampler2D u_curve;
uniform vec3 u_v0, u_v1, u_m0, u_m1;
uniform vec2 u_texel, u_outSize;
uniform float u_exposure, u_contrast, u_highlights, u_shadows, u_whites, u_blacks;
uniform float u_warmth, u_tint, u_hue, u_sat, u_vibrance;
uniform float u_grey, u_levels, u_notan, u_split, u_paletteN, u_opaque, u_outside;
uniform float u_curveOn, u_mixOn, u_gradeOn;
uniform vec3 u_mix[8];
uniform vec3 u_gShadow, u_gMid, u_gHigh, u_gLum;
uniform float u_gBlend, u_gBalance;
uniform float u_texture, u_clarity, u_dehaze;
uniform float u_vignette, u_vigMid, u_vigFeather, u_grain, u_grainSize;
uniform float u_sharpen, u_sharpRadius, u_noise, u_noiseColour;
uniform vec3 u_palette[16];
const vec3 LUMA = vec3(0.299, 0.587, 0.114);
vec3 rgb2hsv(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y); float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
// Noise reduction: neighbours that look like this pixel are averaged in.
vec3 denoise(vec2 s, vec3 c0) {
  vec3 sum = vec3(0.0); float wsum = 0.0;
  for (int j = -2; j <= 2; j++) {
    for (int i = -2; i <= 2; i++) {
      vec2 d = vec2(float(i), float(j));
      vec3 c = texture2D(u_img, s + d * u_texel * 1.5).rgb;
      vec3 df = c - c0;
      float w = exp(-dot(d, d) * 0.18 - dot(df, df) * 60.0);
      sum += c * w; wsum += w;
    }
  }
  vec3 avg = sum / wsum;
  float l0 = dot(c0, LUMA); float la = dot(avg, LUMA);
  float l = mix(l0, la, u_noise);
  vec3 ch = mix(c0 - l0, avg - la, u_noiseColour);
  return clamp(vec3(l) + ch, 0.0, 1.0);
}
// A colour's share of one band of the mixer: 1 at the band's hue, 0 at its neighbours'. Hues in turns.
float band(float h, float c, float lo, float hi) {
  float d = h - c; d -= floor(d + 0.5);
  float wl = c - lo; wl -= floor(wl);
  float wr = hi - c; wr -= floor(wr);
  return d < 0.0 ? max(0.0, 1.0 + d / wl) : max(0.0, 1.0 - d / wr);
}
vec3 mixer(vec3 c) {
  vec3 h = rgb2hsv(c);
  vec3 m = band(h.x, 0.0, 300.0 / 360.0, 30.0 / 360.0) * u_mix[0]
    + band(h.x, 30.0 / 360.0, 0.0, 60.0 / 360.0) * u_mix[1]
    + band(h.x, 60.0 / 360.0, 30.0 / 360.0, 120.0 / 360.0) * u_mix[2]
    + band(h.x, 120.0 / 360.0, 60.0 / 360.0, 180.0 / 360.0) * u_mix[3]
    + band(h.x, 180.0 / 360.0, 120.0 / 360.0, 240.0 / 360.0) * u_mix[4]
    + band(h.x, 240.0 / 360.0, 180.0 / 360.0, 270.0 / 360.0) * u_mix[5]
    + band(h.x, 270.0 / 360.0, 240.0 / 360.0, 300.0 / 360.0) * u_mix[6]
    + band(h.x, 300.0 / 360.0, 270.0 / 360.0, 0.0) * u_mix[7];
  float k = smoothstep(0.02, 0.2, h.y);                       // greys are left alone
  h.x = fract(h.x + m.x * (30.0 / 360.0) * k + 1.0);
  h.y = clamp(h.y * (1.0 + m.y * k), 0.0, 1.0);
  h.z = clamp(h.z * (1.0 + m.z * 0.5 * k), 0.0, 1.0);
  return hsv2rgb(h);
}
vec3 grade(vec3 c) {
  float l = dot(c, LUMA);
  float b = u_gBalance * 0.25;
  float ws = 1.0 - smoothstep(0.0, mix(0.35, 0.75, u_gBlend) + b, l);
  float wh = smoothstep(mix(0.65, 0.25, u_gBlend) + b, 1.0, l);
  float wm = clamp(1.0 - ws - wh, 0.0, 1.0);
  c += ws * u_gShadow + wm * u_gMid + wh * u_gHigh;
  c += (ws * u_gLum.x + wm * u_gLum.y + wh * u_gLum.z) * 0.25;
  return clamp(c, 0.0, 1.0);
}
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
void main() {
  vec3 q = vec3(v_uv, 1.0);
  vec2 o = vec2(dot(u_v0, q), dot(u_v1, q));
  bool outside = o.x < 0.0 || o.x > 1.0 || o.y < 0.0 || o.y > 1.0;
  if (outside && u_outside < 0.5) { gl_FragColor = vec4(0.0); return; }
  vec3 oq = vec3(o, 1.0);
  vec2 s = vec2(dot(u_m0, oq), dot(u_m1, oq));
  if (outside && (s.x < 0.0 || s.x > 1.0 || s.y < 0.0 || s.y > 1.0)) { gl_FragColor = vec4(0.0); return; }
  vec4 t = texture2D(u_img, s);
  vec3 c = t.rgb;
  vec3 orig = c;
  if (u_noise > 0.0005 || u_noiseColour > 0.0005) c = denoise(s, c);
  vec3 src = c;
  c *= pow(2.0, u_exposure);
  float l = dot(c, LUMA);
  float sw = 1.0 - smoothstep(0.0, 0.6, l);
  float hw = smoothstep(0.4, 1.0, l);
  c += u_shadows * sw * 0.5 * (1.0 - c);
  c += u_highlights * hw * 0.5 * c;
  if (abs(u_whites) > 0.0005) c += u_whites * 0.25 * smoothstep(0.55, 1.0, l);
  if (abs(u_blacks) > 0.0005) c += u_blacks * 0.25 * (1.0 - smoothstep(0.0, 0.45, l));
  c = (c - 0.5) * (1.0 + u_contrast) + 0.5;
  c.r += u_warmth * 0.12; c.b -= u_warmth * 0.12; c.g -= u_tint * 0.1;
  c = clamp(c, 0.0, 1.0);
  if (u_curveOn > 0.5) {
    c = vec3(texture2D(u_curve, vec2((c.r * 1023.0 + 0.5) / 1024.0, 0.5)).r,
      texture2D(u_curve, vec2((c.g * 1023.0 + 0.5) / 1024.0, 0.5)).g,
      texture2D(u_curve, vec2((c.b * 1023.0 + 0.5) / 1024.0, 0.5)).b);
  }
  if (abs(u_texture) > 0.0005 || abs(u_clarity) > 0.0005 || abs(u_dehaze) > 0.0005) {
    vec3 bs = texture2D(u_blurS, s).rgb;
    vec3 bl = texture2D(u_blurL, s).rgb;
    if (u_dehaze > 0.0005) {
      float dark = min(bl.r, min(bl.g, bl.b));
      float tr = max(0.15, 1.0 - u_dehaze * 0.85 * dark);
      c = (c - 1.0) / tr + 1.0;
      c = mix(vec3(dot(c, LUMA)), c, 1.0 + u_dehaze * 0.25);
    } else if (u_dehaze < -0.0005) {
      float dark = min(bl.r, min(bl.g, bl.b));
      c = mix(c, vec3(1.0), -u_dehaze * 0.5 * (0.35 + 0.65 * dark));
    }
    float lm = clamp(dot(c, LUMA), 0.0, 1.0);
    c += u_texture * 1.2 * (src - bs);
    c += u_clarity * 0.9 * (src - bl) * (1.0 - pow(abs(2.0 * lm - 1.0), 2.0));
    c = clamp(c, 0.0, 1.0);
  }
  if (u_sharpen > 0.0005) {
    vec2 d = u_texel * u_sharpRadius;
    vec3 n = (texture2D(u_img, s + vec2(d.x, 0.0)).rgb + texture2D(u_img, s - vec2(d.x, 0.0)).rgb
      + texture2D(u_img, s + vec2(0.0, d.y)).rgb + texture2D(u_img, s - vec2(0.0, d.y)).rgb) * 0.25;
    c = clamp(c + u_sharpen * 1.5 * (src - n), 0.0, 1.0);
  }
  if (abs(u_hue) > 0.0005 || abs(u_sat) > 0.0005) {
    vec3 h = rgb2hsv(c); h.x = fract(h.x + u_hue); h.y = clamp(h.y * (1.0 + u_sat), 0.0, 1.0); c = hsv2rgb(h);
  }
  if (abs(u_vibrance) > 0.0005) {
    float mx = max(c.r, max(c.g, c.b)); float mn = min(c.r, min(c.g, c.b));
    float g = dot(c, LUMA);
    c = clamp(mix(vec3(g), c, 1.0 + u_vibrance * (1.0 - (mx - mn))), 0.0, 1.0);
  }
  if (u_mixOn > 0.5) c = mixer(c);
  if (u_gradeOn > 0.5) c = grade(c);
  float lum = dot(c, LUMA);
  if (u_grey > 0.5) c = vec3(lum);
  if (u_notan > 0.0) c = vec3(step(u_notan, lum));
  else if (u_levels >= 2.0) c = clamp(floor(c * u_levels) / (u_levels - 1.0), 0.0, 1.0);
  if (u_paletteN > 0.5) {
    vec3 best = u_palette[0]; float bd = 1.0e9;
    for (int i = 0; i < 16; i++) {
      if (float(i) >= u_paletteN) break;
      vec3 d = c - u_palette[i]; float dd = dot(d, d);
      if (dd < bd) { bd = dd; best = u_palette[i]; }
    }
    c = best;
  }
  if (!outside && abs(u_vignette) > 0.0005) {
    float d = length((o - 0.5) * 2.0) / 1.41421356;            // 0 at the centre, 1 in a corner
    float inner = 0.9 * u_vigMid;
    float v = smoothstep(inner, inner + mix(0.1, 1.0, u_vigFeather), d);
    c = u_vignette < 0.0 ? c * (1.0 + u_vignette * v) : c + u_vignette * v * (1.0 - c);
  }
  if (!outside && u_grain > 0.0005) {
    vec2 g = floor(o * u_outSize / mix(1.0, 4.0, u_grainSize));
    float n = hash(g) + hash(g + 17.0) - 1.0;
    float gm = dot(c, LUMA);
    c = clamp(c + u_grain * 0.18 * n * (1.0 - 0.6 * abs(2.0 * gm - 1.0)), 0.0, 1.0);
  }
  if (u_split >= 0.0 && v_uv.x < u_split) c = orig;
  if (outside) c *= 0.3;
  gl_FragColor = vec4(c, (u_opaque > 0.5 || outside) ? 1.0 : t.a);
}`;

const MO_ENGINE_LOOK_KEYS = ['exposure', 'contrast', 'highlights', 'shadows', 'whites', 'blacks', 'warmth', 'tint', 'hue', 'saturation', 'vibrance'];
const MO_ENGINE_FLOATS = [['u_exposure', 'exposure'], ['u_contrast', 'contrast'], ['u_highlights', 'highlights'], ['u_shadows', 'shadows'], ['u_whites', 'whites'], ['u_blacks', 'blacks'],
  ['u_warmth', 'warmth'], ['u_tint', 'tint'], ['u_hue', 'hue'], ['u_sat', 'saturation'], ['u_vibrance', 'vibrance'],
  ['u_texture', 'texture'], ['u_clarity', 'clarity'], ['u_dehaze', 'dehaze'],
  ['u_vignette', 'vignette'], ['u_vigMid', 'vignetteMid'], ['u_vigFeather', 'vignetteFeather'], ['u_grain', 'grain'], ['u_grainSize', 'grainSize'],
  ['u_sharpen', 'sharpen'], ['u_sharpRadius', 'sharpenRadius'], ['u_noise', 'noise'], ['u_noiseColour', 'noiseColour']];
const MO_ENGINE_IDENTITY = [1, 0, 0, 0, 1, 0];
const MO_ENGINE_CURVE_N = 1024;

function moImageEngine(canvas) {
  const attrs = { preserveDrawingBuffer: true, premultipliedAlpha: false, antialias: false };
  const gl = canvas.getContext('webgl2', attrs) || canvas.getContext('webgl', attrs);
  if (!gl) return null;
  const gl2 = typeof WebGL2RenderingContext !== 'undefined' && gl instanceof WebGL2RenderingContext;
  const compile = (type, src) => { const sh = gl.createShader(type); gl.shaderSource(sh, src); gl.compileShader(sh); if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) throw new Error(gl.getShaderInfoLog(sh) || 'shader'); return sh; };
  const link = (vs, fs) => {
    const p = gl.createProgram();
    gl.attachShader(p, compile(gl.VERTEX_SHADER, vs));
    gl.attachShader(p, compile(gl.FRAGMENT_SHADER, fs));
    gl.bindAttribLocation(p, 0, 'a_pos');
    gl.linkProgram(p);
    if (!gl.getProgramParameter(p, gl.LINK_STATUS)) throw new Error(gl.getProgramInfoLog(p) || 'program');
    return p;
  };
  const prog = link(MO_PLAN_VS, MO_ENGINE_FS);
  const blurProg = link(MO_ENGINE_COPY_VS, MO_ENGINE_BLUR_FS);
  const buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0);
  gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  const U = {};
  for (const n of ['u_img', 'u_blurS', 'u_blurL', 'u_curve', 'u_v0', 'u_v1', 'u_m0', 'u_m1', 'u_texel', 'u_outSize',
    'u_grey', 'u_levels', 'u_notan', 'u_split', 'u_paletteN', 'u_palette', 'u_opaque', 'u_outside',
    'u_curveOn', 'u_mixOn', 'u_gradeOn', 'u_mix', 'u_gShadow', 'u_gMid', 'u_gHigh', 'u_gLum', 'u_gBlend', 'u_gBalance',
    ...MO_ENGINE_FLOATS.map((f) => f[0])]) U[n] = gl.getUniformLocation(prog, n);
  const BU = { img: gl.getUniformLocation(blurProg, 'u_img'), step: gl.getUniformLocation(blurProg, 'u_step') };
  const plainTexture = (filter) => {
    const t = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, t);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, filter || gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, filter || gl.LINEAR);
    return t;
  };
  const tex = plainTexture();
  const maxTex = gl.getParameter(gl.MAX_TEXTURE_SIZE) || 4096;
  let srcW = 0, srcH = 0;

  // A texture that can be drawn into.
  const targets = [];
  const target = (w, h) => {
    const t = plainTexture();
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, w, h, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
    const fb = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, fb);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, t, 0);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    const o = { tex: t, fb, w, h };
    targets.push(o);
    return o;
  };
  const release = (o) => { if (!o) return; try { gl.deleteFramebuffer(o.fb); gl.deleteTexture(o.tex); } catch { /* gone */ } const i = targets.indexOf(o); if (i >= 0) targets.splice(i, 1); };
  const pass = (from, to, stepX, stepY) => {
    gl.bindFramebuffer(gl.FRAMEBUFFER, to.fb);
    gl.viewport(0, 0, to.w, to.h);
    gl.useProgram(blurProg);
    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, from);
    gl.uniform1i(BU.img, 0);
    gl.uniform2f(BU.step, stepX, stepY);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  };

  // The two blurred copies: the source halved to a quarter (fine detail) and
  // to a sixteenth (broad shapes), each then blurred. Made when first needed.
  let blurS = null, blurL = null;
  const dropBlur = () => { release(blurS); release(blurL); blurS = null; blurL = null; };
  const ensureBlur = () => {
    if (blurS || !srcW) return;
    const levels = [];
    let from = tex; let w = srcW; let h = srcH;
    for (let i = 0; i < 4; i++) {
      w = Math.max(1, Math.round(w / 2)); h = Math.max(1, Math.round(h / 2));
      const t = target(w, h);
      pass(from, t, 0, 0);
      levels.push(t);
      from = t.tex;
    }
    const blurred = (level) => {
      const a = target(level.w, level.h); const b = target(level.w, level.h);
      pass(level.tex, a, 1 / level.w, 0);
      pass(a.tex, b, 0, 1 / level.h);
      release(a);
      return b;
    };
    blurS = blurred(levels[1]);
    blurL = blurred(levels[3]);
    for (const t of levels) release(t);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
  };

  // The tone curve as a strip of 1024 values per channel; uploaded when it changes.
  const curveTex = plainTexture();
  let curveData = null;
  const setCurve = (data) => {
    if (data === curveData) return;
    curveData = data;
    gl.bindTexture(gl.TEXTURE_2D, curveTex);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
    gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, MO_ENGINE_CURVE_N, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, data);
  };

  const apply = (p, W, H) => {
    gl.viewport(0, 0, W, H);
    gl.useProgram(prog);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    const v = p.view || MO_ENGINE_IDENTITY; const m = p.m || MO_ENGINE_IDENTITY;
    gl.uniform3f(U.u_v0, v[0], v[1], v[2]); gl.uniform3f(U.u_v1, v[3], v[4], v[5]);
    gl.uniform3f(U.u_m0, m[0], m[1], m[2]); gl.uniform3f(U.u_m1, m[3], m[4], m[5]);
    gl.uniform2f(U.u_texel, 1 / Math.max(1, srcW), 1 / Math.max(1, srcH));
    const out = p.outSize || [W, H];
    gl.uniform2f(U.u_outSize, out[0], out[1]);
    const look = p.look || {};
    for (const [u, k] of MO_ENGINE_FLOATS) gl.uniform1f(U[u], Number(look[k]) || 0);
    gl.uniform1f(U.u_grey, p.grey ? 1 : 0); gl.uniform1f(U.u_levels, Number(p.levels) || 0); gl.uniform1f(U.u_notan, Number(p.notan) || 0);
    gl.uniform1f(U.u_split, typeof p.split === 'number' ? p.split : -1);
    gl.uniform1f(U.u_opaque, p.opaque ? 1 : 0);
    gl.uniform1f(U.u_outside, p.outside ? 1 : 0);
    const sw = Array.isArray(p.palette) ? p.palette : [];
    const arr = new Float32Array(48);
    sw.slice(0, 16).forEach((s, i) => { arr[i * 3] = s[0] / 255; arr[i * 3 + 1] = s[1] / 255; arr[i * 3 + 2] = s[2] / 255; });
    gl.uniform3fv(U.u_palette, arr);
    gl.uniform1f(U.u_paletteN, Math.min(16, sw.length));
    gl.uniform1f(U.u_curveOn, p.curve ? 1 : 0);
    gl.uniform1f(U.u_mixOn, p.mix ? 1 : 0);
    if (p.mix) gl.uniform3fv(U.u_mix, p.mix);
    const g = p.grade;
    gl.uniform1f(U.u_gradeOn, g ? 1 : 0);
    if (g) {
      gl.uniform3f(U.u_gShadow, g.shadow[0], g.shadow[1], g.shadow[2]);
      gl.uniform3f(U.u_gMid, g.mid[0], g.mid[1], g.mid[2]);
      gl.uniform3f(U.u_gHigh, g.high[0], g.high[1], g.high[2]);
      gl.uniform3f(U.u_gLum, g.lum[0], g.lum[1], g.lum[2]);
      gl.uniform1f(U.u_gBlend, g.blend); gl.uniform1f(U.u_gBalance, g.balance);
    }
    gl.uniform1i(U.u_img, 0); gl.uniform1i(U.u_blurS, 1); gl.uniform1i(U.u_blurL, 2); gl.uniform1i(U.u_curve, 3);
    gl.activeTexture(gl.TEXTURE1); gl.bindTexture(gl.TEXTURE_2D, blurS ? blurS.tex : tex);
    gl.activeTexture(gl.TEXTURE2); gl.bindTexture(gl.TEXTURE_2D, blurL ? blurL.tex : tex);
    gl.activeTexture(gl.TEXTURE3); gl.bindTexture(gl.TEXTURE_2D, curveTex);
    gl.activeTexture(gl.TEXTURE0); gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  };
  const prepare = (p) => {
    const look = p.look || {};
    if (Number(look.texture) || Number(look.clarity) || Number(look.dehaze)) ensureBlur();
    if (p.curve) setCurve(p.curve);
  };
  setCurve(new Uint8Array(MO_ENGINE_CURVE_N * 4));

  return {
    maxTexture: maxTex,
    // source: an Image, ImageBitmap or canvas. opts.blurPx bakes a squint blur
    // into the texture; opts.smooth keeps a shrunken view clean (WebGL2 only).
    setSource(source, opts) {
      const o = opts || {};
      const blurPx = Number(o.blurPx) || 0;
      let w = source.naturalWidth || source.width; let h = source.naturalHeight || source.height;
      const scale = Math.min(1, maxTex / Math.max(w, h));
      let up = source;
      if (scale < 1 || blurPx > 0) {
        const cv = document.createElement('canvas');
        cv.width = Math.max(1, Math.round(w * scale)); cv.height = Math.max(1, Math.round(h * scale));
        const ctx = cv.getContext('2d');
        if (blurPx > 0) ctx.filter = `blur(${blurPx * scale}px)`;
        ctx.drawImage(source, 0, 0, cv.width, cv.height);
        up = cv; w = cv.width; h = cv.height;
      }
      gl.activeTexture(gl.TEXTURE0);
      gl.bindTexture(gl.TEXTURE_2D, tex);
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
      gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
      gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, up);
      const smooth = gl2 && o.smooth === true;
      if (smooth) gl.generateMipmap(gl.TEXTURE_2D);
      gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, smooth ? gl.LINEAR_MIPMAP_LINEAR : gl.LINEAR);
      srcW = w; srcH = h;
      dropBlur();
    },
    get size() { return { w: srcW, h: srcH }; },
    // p: { view, m, outSize, look, curve, mix, grade, grey, levels, notan, palette, split, opaque, outside }
    draw(p, width, height) {
      const W = Math.max(1, Math.round(width)); const H = Math.max(1, Math.round(height));
      if (canvas.width !== W) canvas.width = W;
      if (canvas.height !== H) canvas.height = H;
      prepare(p);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      apply(p, W, H);
    },
    // The same drawing at a small size, handed back as RGBA bytes (rows top to bottom).
    sample(p, width, height) {
      const W = Math.max(1, Math.round(width)); const H = Math.max(1, Math.round(height));
      prepare(p);
      const t = target(W, H);
      gl.bindFramebuffer(gl.FRAMEBUFFER, t.fb);
      apply(p, W, H);
      const raw = new Uint8Array(W * H * 4);
      gl.readPixels(0, 0, W, H, gl.RGBA, gl.UNSIGNED_BYTE, raw);
      gl.bindFramebuffer(gl.FRAMEBUFFER, null);
      release(t);
      const out = new Uint8Array(raw.length);
      for (let y = 0; y < H; y++) out.set(raw.subarray((H - 1 - y) * W * 4, (H - y) * W * 4), y * W * 4);
      return out;
    },
    dispose() {
      try {
        for (const t of targets.slice()) release(t);
        gl.deleteTexture(tex); gl.deleteTexture(curveTex); gl.deleteBuffer(buf); gl.deleteProgram(prog); gl.deleteProgram(blurProg);
        const ext = gl.getExtension('WEBGL_lose_context'); if (ext) ext.loseContext();
      } catch { /* gone */ }
    },
  };
}

// Painting Plans on the shared engine: a plan recipe has a canvas-locked crop,
// quarter turns and flips (no straighten), and is always opaque.
function moPlanRenderer(canvas) {
  const engine = moImageEngine(canvas);
  if (!engine) return null;
  return {
    maxTexture: engine.maxTexture,
    setSource(source, blurPx) { engine.setSource(source, { blurPx }); },
    get size() { return engine.size; },
    // opts: { width, height, full (ignore the crop), split (-1 or 0..1) }
    render(recipe, opts) {
      const r = recipe;
      const size = engine.size;
      const geo = moEditAffine({ crop: opts.full ? { x: 0, y: 0, w: 1, h: 1 } : r.crop, angle: 0, rotate: r.rotate, flipH: r.flipH, flipV: r.flipV }, size.w, size.h);
      const look = {};
      for (const k of MO_ENGINE_LOOK_KEYS) look[k] = r[k];
      engine.draw({
        m: geo.m, look, opaque: true,
        grey: r.grey, levels: r.levels, notan: r.notan,
        palette: r.palette && r.palette.apply ? r.palette.swatches : [],
        split: typeof opts.split === 'number' ? opts.split : -1,
      }, opts.width, opts.height);
    },
    dispose() { engine.dispose(); },
  };
}

// Draw the composition overlays onto a 2D context the size of the crop.
function moPlanDrawOverlays(ctx, W, H, recipe, canvasW, canvasH, scale) {
  const o = recipe.overlays;
  ctx.clearRect(0, 0, W, H);
  const line = (x1, y1, x2, y2, color, width) => { ctx.strokeStyle = color; ctx.lineWidth = width; ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); };
  const k = scale || 1;
  const white = 'rgba(255,255,255,0.85)'; const dark = 'rgba(0,0,0,0.45)';
  const dual = (x1, y1, x2, y2, w) => { line(x1, y1, x2, y2, dark, (w + 1.5) * k); line(x1, y1, x2, y2, white, w * k); };
  if (o.thirds) { for (const f of [1 / 3, 2 / 3]) { dual(W * f, 0, W * f, H, 1); dual(0, H * f, W, H * f, 1); } }
  if (o.golden) { for (const f of [0.382, 0.618]) { dual(W * f, 0, W * f, H, 1); dual(0, H * f, W, H * f, 1); } }
  if (o.diagonals) { dual(0, 0, W, H, 1); dual(W, 0, 0, H, 1); }
  if (o.grid) {
    const g = moPlanGridLines(canvasW, canvasH, o.gridInches);
    for (const x of g.xs) dual(W * x, 0, W * x, H, 0.8);
    for (const y of g.ys) dual(0, H * y, W, H * y, 0.8);
    ctx.font = `${Math.max(9, Math.round(11 * k))}px sans-serif`;
    ctx.textBaseline = 'top';
    const label = (t, x, y) => { ctx.fillStyle = dark; ctx.fillRect(x - 1, y - 1, ctx.measureText(t).width + 4, 12 * k + 2); ctx.fillStyle = white; ctx.fillText(t, x + 1, y); };
    const step = o.gridInches > 0 ? o.gridInches : 1;
    for (let i = 0; i < g.cols; i++) label(String(i + 1), (W * i * step) / canvasW + 3 * k, 2 * k);
    for (let j = 0; j < g.rows; j++) label(String.fromCharCode(65 + (j % 26)), 3 * k, (H * j * step) / canvasH + 14 * k);
  }
}

// ── The editor ─────────────────────────────────────────────────────────────

function renderPlanEditor(container, api, planId) {
  moInjectStyles();
  const root = moEl('div', 'mo-plan');
  root.tabIndex = 0;
  container.appendChild(root);
  let disposed = false;
  const state = { plan: null, variants: [], media: [], variant: null, recipe: null, tool: 'light', image: null, imgW: 0, imgH: 0, srcPath: null, split: -1, mirror: false, blurBaked: 0 };
  const history = []; let histIdx = -1;
  let renderer = null; let saveTimer = null; let raf = 0;

  // Layout: tools strip | panel | stage (+ variations below)
  const tools = moEl('div', 'mo-plan-tools');
  const panel = moEl('div', 'mo-plan-panel');
  const main = moEl('div', 'mo-plan-main');
  const stage = moEl('div', 'mo-plan-stage');
  const glCanvas = moEl('canvas', 'mo-plan-canvas');
  const ovCanvas = moEl('canvas', 'mo-plan-overlay');
  const cropBox = moEl('div', 'mo-plan-cropbox mo-hidden');
  for (const c of ['nw', 'ne', 'sw', 'se']) cropBox.appendChild(moEl('div', `mo-plan-crophandle mo-plan-crophandle--${c}`, { 'data-corner': c }));
  const frame = moEl('div', 'mo-plan-frame');
  frame.appendChild(glCanvas); frame.appendChild(ovCanvas); frame.appendChild(cropBox);
  stage.appendChild(frame);
  const variantsBar = moEl('div', 'mo-plan-variants');
  const topbar = moEl('div', 'mo-plan-topbar');
  main.appendChild(topbar); main.appendChild(stage); main.appendChild(variantsBar);
  root.appendChild(tools); root.appendChild(panel); root.appendChild(main);

  const TOOLS = [['crop', 'crop', 'Crop'], ['light', 'sun', 'Light'], ['colour', 'droplet', 'Colour'], ['values', 'contrast', 'Values'], ['grids', 'grid-3x3', 'Composition'], ['palette', 'palette', 'Palette'], ['compare', 'columns', 'Compare'], ['process', 'layers', 'Process'], ['info', 'pencil', 'Plan']];
  const toolBtns = {};
  for (const [id, icon, label] of TOOLS) {
    const b = moEl('button', 'mo-plan-tool', { type: 'button', title: label, 'aria-label': label, innerHTML: moIcon(icon, 16) });
    b.addEventListener('click', () => setTool(id));
    toolBtns[id] = b;
    tools.appendChild(b);
  }

  // Top bar: title, undo/redo, export.
  const titleEl = moEl('div', 'mo-plan-title');
  const sizeEl = moEl('div', 'mo-practice-dim');
  const undoBtn = moEl('button', 'mo-practice-btn', { type: 'button', title: 'Undo', 'aria-label': 'Undo', innerHTML: moIcon('rotate-cw', 14) });
  undoBtn.style.transform = 'scaleX(-1)';
  const redoBtn = moEl('button', 'mo-practice-btn', { type: 'button', title: 'Redo', 'aria-label': 'Redo', innerHTML: moIcon('rotate-cw', 14) });
  undoBtn.addEventListener('click', () => undo()); redoBtn.addEventListener('click', () => redo());
  const exportBtn = moEl('button', 'mo-practice-start', { type: 'button', textContent: 'Export Plan' });
  const exportGridBtn = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Export With Grid' });
  const printBtn = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Print With Grid' });
  exportBtn.addEventListener('click', () => void exportPlan(false));
  exportGridBtn.addEventListener('click', () => void exportPlan(true));
  printBtn.addEventListener('click', () => void printPlan());
  const left = moEl('div', 'mo-plan-topbar-left'); left.appendChild(titleEl); left.appendChild(sizeEl);
  const right = moEl('div', 'mo-plan-topbar-right');
  for (const b of [undoBtn, redoBtn, exportGridBtn, printBtn, exportBtn]) right.appendChild(b);
  topbar.appendChild(left); topbar.appendChild(right);

  // ── helpers ──
  const aspect = () => (state.plan.canvas_w > 0 && state.plan.canvas_h > 0) ? state.plan.canvas_w / state.plan.canvas_h : 0.8;
  const rotated = () => moPlanRotatedSize(state.imgW, state.imgH, state.recipe.rotate);
  function pushHistory() {
    const snap = JSON.stringify(state.recipe);
    if (history[histIdx] === snap) return;
    history.splice(histIdx + 1);
    history.push(snap);
    if (history.length > 60) history.shift();
    histIdx = history.length - 1;
    syncUndo();
  }
  function syncUndo() { undoBtn.disabled = histIdx <= 0; redoBtn.disabled = histIdx >= history.length - 1; }
  function undo() { if (histIdx > 0) { histIdx--; state.recipe = moPlanNormalizeRecipe(JSON.parse(history[histIdx])); state.variant.recipe = state.recipe; afterRecipeChange(false); } }
  function redo() { if (histIdx < history.length - 1) { histIdx++; state.recipe = moPlanNormalizeRecipe(JSON.parse(history[histIdx])); state.variant.recipe = state.recipe; afterRecipeChange(false); } }
  function scheduleSave() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(async () => {
      if (disposed || !state.variant) return;
      try {
        await db.run('UPDATE mo_plan_variants SET recipe_json = ?, updated_at = ? WHERE id = ?', [JSON.stringify(state.recipe), new Date().toISOString(), state.variant.id]);
        await db.run('UPDATE mo_plans SET title = ?, notes = ?, canvas_w = ?, canvas_h = ?, updated_at = ? WHERE id = ?', [state.plan.title, state.plan.notes || '', state.plan.canvas_w, state.plan.canvas_h, new Date().toISOString(), planId]);
        document.dispatchEvent(new CustomEvent('mo:plans-changed'));
      } catch (err) { console.warn('[media-organizer] plan save failed:', err && err.message); }
    }, 400);
  }
  // record: true when the change is a user edit worth an undo step
  function afterRecipeChange(record) {
    if (record !== false) pushHistory();
    if (state.recipe.blur !== state.blurBaked) bakeSource();
    requestRender();
    scheduleSave();
    renderPanel();
    refreshVariantThumb(state.variant);
  }
  function bakeSource() {
    if (!renderer || !state.image) return;
    const px = state.recipe.blur > 0 ? (state.recipe.blur * Math.max(state.imgW, state.imgH)) / 100 : 0;
    renderer.setSource(state.image, px);
    state.blurBaked = state.recipe.blur;
  }
  function requestRender() { if (raf) return; raf = requestAnimationFrame(() => { raf = 0; draw(); }); }

  function stageBox() {
    const sw = stage.clientWidth - 24; const sh = stage.clientHeight - 24;
    return { w: Math.max(50, sw), h: Math.max(50, sh) };
  }
  // The frame holds the full rotated image in the crop tool, the crop elsewhere.
  function draw() {
    if (disposed || !renderer || !state.recipe) return;
    const r = state.recipe;
    const rs = rotated();
    const full = state.tool === 'crop';
    const contentW = full ? rs.w : rs.w * r.crop.w;
    const contentH = full ? rs.h : rs.h * r.crop.h;
    const box = stageBox();
    const k = Math.min(box.w / contentW, box.h / contentH);
    const cssW = Math.max(1, Math.round(contentW * k)); const cssH = Math.max(1, Math.round(contentH * k));
    const dpr = window.devicePixelRatio || 1;
    frame.style.width = cssW + 'px'; frame.style.height = cssH + 'px';
    frame.style.transform = state.mirror ? 'scaleX(-1)' : '';
    glCanvas.style.width = cssW + 'px'; glCanvas.style.height = cssH + 'px';
    renderer.render(r, { width: Math.round(cssW * dpr), height: Math.round(cssH * dpr), full, split: state.tool === 'compare' ? state.split : -1 });
    ovCanvas.width = Math.round(cssW * dpr); ovCanvas.height = Math.round(cssH * dpr);
    ovCanvas.style.width = cssW + 'px'; ovCanvas.style.height = cssH + 'px';
    const octx = ovCanvas.getContext('2d');
    if (full) {
      octx.clearRect(0, 0, ovCanvas.width, ovCanvas.height);
      octx.fillStyle = 'rgba(0,0,0,0.55)';
      const cx = r.crop.x * ovCanvas.width, cy = r.crop.y * ovCanvas.height, cw = r.crop.w * ovCanvas.width, ch = r.crop.h * ovCanvas.height;
      octx.fillRect(0, 0, ovCanvas.width, cy); octx.fillRect(0, cy + ch, ovCanvas.width, ovCanvas.height - cy - ch);
      octx.fillRect(0, cy, cx, ch); octx.fillRect(cx + cw, cy, ovCanvas.width - cx - cw, ch);
      cropBox.classList.remove('mo-hidden');
      cropBox.style.left = (r.crop.x * cssW) + 'px'; cropBox.style.top = (r.crop.y * cssH) + 'px';
      cropBox.style.width = (r.crop.w * cssW) + 'px'; cropBox.style.height = (r.crop.h * cssH) + 'px';
    } else {
      cropBox.classList.add('mo-hidden');
      moPlanDrawOverlays(octx, ovCanvas.width, ovCanvas.height, r, state.plan.canvas_w, state.plan.canvas_h, dpr);
    }
  }
  const resizeObs = ('ResizeObserver' in window) ? new ResizeObserver(() => requestRender()) : null;
  if (resizeObs) resizeObs.observe(stage);

  // ── crop dragging ──
  let drag = null;
  cropBox.addEventListener('pointerdown', (e) => {
    if (state.tool !== 'crop') return;
    e.preventDefault();
    const corner = e.target && e.target.dataset ? e.target.dataset.corner : null;
    drag = { corner: corner || null, x0: e.clientX, y0: e.clientY, crop: Object.assign({}, state.recipe.crop), fw: frame.clientWidth, fh: frame.clientHeight };
    cropBox.setPointerCapture(e.pointerId);
  });
  cropBox.addEventListener('pointermove', (e) => {
    if (!drag) return;
    const rs = rotated();
    const dx = (e.clientX - drag.x0) / drag.fw; const dy = (e.clientY - drag.y0) / drag.fh;
    const c = drag.crop;
    let next;
    if (!drag.corner) next = { x: c.x + dx, y: c.y + dy, w: c.w, h: c.h };
    else {
      const signX = drag.corner.includes('e') ? 1 : -1;
      const grow = signX * dx;
      const w = Math.max(0.02, c.w + grow);
      const h = (w * rs.w) / (aspect() * rs.h);
      next = { w, h, x: drag.corner.includes('w') ? c.x + (c.w - w) : c.x, y: drag.corner.includes('n') ? c.y + (c.h - h) : c.y };
    }
    state.recipe.crop = moPlanClampCrop(next, rs.w, rs.h, aspect());
    requestRender();
  });
  const endDrag = () => { if (drag) { drag = null; afterRecipeChange(true); } };
  cropBox.addEventListener('pointerup', endDrag);
  cropBox.addEventListener('pointercancel', endDrag);

  // ── panel ──
  function setTool(id) {
    state.tool = id;
    for (const k of Object.keys(toolBtns)) toolBtns[k].classList.toggle('is-on', k === id);
    renderPanel();
    requestRender();
  }
  const slider = (label, key, min, max, step, fmt) => {
    const row = moEl('div', 'mo-plan-slider');
    const head = moEl('div', 'mo-plan-slider-head');
    head.appendChild(moEl('span', null, { textContent: label }));
    const val = moEl('span', 'mo-practice-dim');
    head.appendChild(val);
    row.appendChild(head);
    const input = moEl('input', null, { type: 'range', min: String(min), max: String(max), step: String(step), 'aria-label': label });
    input.value = String(state.recipe[key]);
    const show = () => { val.textContent = fmt ? fmt(Number(input.value)) : Number(input.value).toFixed(2); };
    show();
    input.addEventListener('input', () => { state.recipe[key] = Number(input.value); show(); if (key !== 'blur') requestRender(); else afterRecipeChange(false); });
    input.addEventListener('change', () => { state.recipe[key] = Number(input.value); afterRecipeChange(true); });
    input.addEventListener('dblclick', () => { input.value = '0'; state.recipe[key] = 0; show(); afterRecipeChange(true); });
    row.appendChild(input);
    return row;
  };
  const toggle = (label, get, set) => {
    const wrap = moEl('label', 'mo-practice-check');
    const input = moEl('input', 'mo-clip-check', { type: 'checkbox' });
    input.checked = !!get();
    input.addEventListener('change', () => set(input.checked));
    wrap.appendChild(input); wrap.appendChild(moEl('span', null, { textContent: label }));
    return wrap;
  };
  const button = (label, fn, primary) => { const b = moEl('button', primary ? 'mo-practice-start' : 'mo-toolbar-btn', { type: 'button', textContent: label }); b.addEventListener('click', fn); return b; };
  const section = (title) => { const s = moEl('div', 'mo-plan-section'); if (title) s.appendChild(moEl('div', 'mo-practice-section-title', { textContent: title })); panel.appendChild(s); return s; };
  const panelDisposers = [];
  function renderPanel() {
    for (const d of panelDisposers.splice(0)) { try { d(); } catch { /* gone */ } }
    panel.innerHTML = '';
    if (!state.recipe) return;
    const r = state.recipe;
    const t = state.tool;
    if (t === 'crop') {
      const s = section('Canvas');
      const row = moEl('div', 'mo-plan-row');
      const wIn = moEl('input', 'mo-clip-input mo-clip-input--xs', { type: 'number', min: '1', max: '120', step: '0.5', 'aria-label': 'Canvas Width' });
      const hIn = moEl('input', 'mo-clip-input mo-clip-input--xs', { type: 'number', min: '1', max: '120', step: '0.5', 'aria-label': 'Canvas Height' });
      wIn.value = String(state.plan.canvas_w); hIn.value = String(state.plan.canvas_h);
      const applySize = () => {
        const w = Math.max(1, Number(wIn.value) || 1); const h = Math.max(1, Number(hIn.value) || 1);
        state.plan.canvas_w = w; state.plan.canvas_h = h;
        const rs = rotated();
        r.crop = moPlanClampCrop(r.crop, rs.w, rs.h, aspect());
        sizeEl.textContent = `${w} × ${h} in`;
        afterRecipeChange(true);
      };
      wIn.addEventListener('change', applySize); hIn.addEventListener('change', applySize);
      row.appendChild(wIn); row.appendChild(moEl('span', 'mo-practice-dim', { textContent: '×' })); row.appendChild(hIn); row.appendChild(moEl('span', 'mo-practice-dim', { textContent: 'in' }));
      s.appendChild(row);
      const presets = moDropdown({ items: [{ value: '', label: 'Common Sizes' }, ...MO_PLAN_CANVAS_PRESETS.map(([w, h]) => ({ value: `${w}x${h}`, label: `${w} × ${h}` }))], selected: '', ariaLabel: 'Common Sizes' });
      presets.onChange = (v) => { if (!v) return; const [w, h] = v.split('x').map(Number); wIn.value = String(w); hIn.value = String(h); applySize(); presets.setValue(''); };
      panelDisposers.push(() => presets.dispose());
      s.appendChild(presets.el);
      const swap = button('Swap Orientation', () => { const w = state.plan.canvas_w; wIn.value = String(state.plan.canvas_h); hIn.value = String(w); applySize(); });
      s.appendChild(swap);
      const s2 = section('Picture');
      const rowR = moEl('div', 'mo-plan-row');
      rowR.appendChild(button('Rotate Left', () => { r.rotate = (r.rotate + 3) % 4; const rs = rotated(); r.crop = moPlanFitCrop(rs.w, rs.h, aspect()); afterRecipeChange(true); }));
      rowR.appendChild(button('Rotate Right', () => { r.rotate = (r.rotate + 1) % 4; const rs = rotated(); r.crop = moPlanFitCrop(rs.w, rs.h, aspect()); afterRecipeChange(true); }));
      s2.appendChild(rowR);
      const rowF = moEl('div', 'mo-plan-row');
      rowF.appendChild(button('Flip Horizontal', () => { r.flipH = !r.flipH; afterRecipeChange(true); }));
      rowF.appendChild(button('Flip Vertical', () => { r.flipV = !r.flipV; afterRecipeChange(true); }));
      s2.appendChild(rowF);
      s2.appendChild(button('Reset Crop', () => { const rs = rotated(); r.crop = moPlanFitCrop(rs.w, rs.h, aspect()); afterRecipeChange(true); }));
      s2.appendChild(moEl('div', 'mo-practice-dim mo-plan-hint', { textContent: 'Drag the box to move it, a corner to resize. The crop keeps the canvas proportions.' }));
    } else if (t === 'light') {
      const s = section('Light');
      s.appendChild(slider('Exposure', 'exposure', -2, 2, 0.01, (v) => (v > 0 ? '+' : '') + v.toFixed(2)));
      s.appendChild(slider('Contrast', 'contrast', -1, 1, 0.01));
      s.appendChild(slider('Highlights', 'highlights', -1, 1, 0.01));
      s.appendChild(slider('Shadows', 'shadows', -1, 1, 0.01));
      s.appendChild(slider('Warmth', 'warmth', -1, 1, 0.01));
      s.appendChild(slider('Tint', 'tint', -1, 1, 0.01));
      s.appendChild(button('Reset Light', () => { Object.assign(r, { exposure: 0, contrast: 0, highlights: 0, shadows: 0, warmth: 0, tint: 0 }); afterRecipeChange(true); }));
    } else if (t === 'colour') {
      const s = section('Colour');
      s.appendChild(slider('Hue', 'hue', -0.5, 0.5, 0.005, (v) => Math.round(v * 360) + '°'));
      s.appendChild(slider('Saturation', 'saturation', -1, 1, 0.01));
      s.appendChild(button('Reset Colour', () => { r.hue = 0; r.saturation = 0; afterRecipeChange(true); }));
    } else if (t === 'values') {
      const s = section('Values');
      s.appendChild(toggle('Greyscale', () => r.grey, (v) => { r.grey = v; afterRecipeChange(true); }));
      const lv = moDropdown({ items: [{ value: '0', label: 'All Values' }, { value: '2', label: '2 Values' }, { value: '3', label: '3 Values' }, { value: '5', label: '5 Values' }], selected: String(r.levels || 0), ariaLabel: 'Values' });
      lv.onChange = (v) => { r.levels = Number(v) || 0; if (r.levels) r.notan = 0; afterRecipeChange(true); };
      panelDisposers.push(() => lv.dispose());
      s.appendChild(lv.el);
      s.appendChild(toggle('Notan', () => r.notan > 0, (v) => { r.notan = v ? 0.5 : 0; if (v) r.levels = 0; afterRecipeChange(true); }));
      if (r.notan > 0) s.appendChild(slider('Threshold', 'notan', 0.05, 0.95, 0.01));
      s.appendChild(slider('Squint', 'blur', 0, 1, 0.02, (v) => Math.round(v * 100) + '%'));
    } else if (t === 'grids') {
      const s = section('Composition');
      s.appendChild(toggle('Thirds', () => r.overlays.thirds, (v) => { r.overlays.thirds = v; afterRecipeChange(true); }));
      s.appendChild(toggle('Golden Section', () => r.overlays.golden, (v) => { r.overlays.golden = v; afterRecipeChange(true); }));
      s.appendChild(toggle('Diagonals', () => r.overlays.diagonals, (v) => { r.overlays.diagonals = v; afterRecipeChange(true); }));
      const s2 = section('Transfer Grid');
      s2.appendChild(toggle('Grid In Inches', () => r.overlays.grid, (v) => { r.overlays.grid = v; afterRecipeChange(true); }));
      const gd = moDropdown({ items: [{ value: '0.5', label: 'Every ½ in' }, { value: '1', label: 'Every 1 in' }, { value: '2', label: 'Every 2 in' }], selected: String(r.overlays.gridInches || 1), ariaLabel: 'Grid Spacing' });
      gd.onChange = (v) => { r.overlays.gridInches = Number(v) || 1; afterRecipeChange(true); };
      panelDisposers.push(() => gd.dispose());
      s2.appendChild(gd.el);
      s2.appendChild(moEl('div', 'mo-practice-dim mo-plan-hint', { textContent: `Rows are lettered, columns numbered, for a ${state.plan.canvas_w} × ${state.plan.canvas_h} in canvas.` }));
    } else if (t === 'palette') {
      const s = section('Palette');
      const cd = moDropdown({ items: [4, 6, 8, 12, 16].map((n) => ({ value: String(n), label: n + ' Colours' })), selected: String(r.palette.count || 8), ariaLabel: 'Colours' });
      cd.onChange = (v) => { r.palette.count = Number(v) || 8; scheduleSave(); };
      panelDisposers.push(() => cd.dispose());
      s.appendChild(cd.el);
      s.appendChild(button('Pull From Picture', () => { extractPalette(); }, true));
      const sw = moEl('div', 'mo-plan-swatches');
      for (const c of r.palette.swatches) {
        const chip = moEl('div', 'mo-plan-swatch', { title: moPlanHex(c) + ' (click to copy)' });
        chip.style.background = moPlanHex(c);
        chip.addEventListener('click', () => { try { navigator.clipboard.writeText(moPlanHex(c)); } catch { /* no clipboard */ } });
        sw.appendChild(chip);
      }
      if (!r.palette.swatches.length) sw.appendChild(moEl('div', 'mo-practice-dim', { textContent: 'No swatches yet.' }));
      s.appendChild(sw);
      s.appendChild(toggle('Limited Palette Preview', () => r.palette.apply, (v) => { r.palette.apply = v; afterRecipeChange(true); }));
    } else if (t === 'compare') {
      const s = section('Compare');
      s.appendChild(toggle('Before And After', () => state.split >= 0, (v) => { state.split = v ? 0.5 : -1; requestRender(); renderPanel(); }));
      if (state.split >= 0) {
        const row = moEl('div', 'mo-plan-slider');
        const input = moEl('input', null, { type: 'range', min: '0', max: '1', step: '0.01', 'aria-label': 'Split' });
        input.value = String(state.split);
        input.addEventListener('input', () => { state.split = Number(input.value); requestRender(); });
        row.appendChild(input);
        s.appendChild(row);
      }
      s.appendChild(toggle('Mirror Check', () => state.mirror, (v) => { state.mirror = v; requestRender(); }));
    } else if (t === 'process') {
      const s = section('Process Shelf');
      if (!state.media.length) s.appendChild(moEl('div', 'mo-practice-dim mo-plan-hint', { textContent: 'Progress photos and clips of this painting. Open one in the library and choose Add To Plan.' }));
      const list = moEl('div', 'mo-plan-shelf');
      for (const m of state.media) {
        const it = moEl('div', 'mo-plan-shelf-item');
        const img = moEl('img', null, { alt: '' });
        it.appendChild(img);
        if (m.kind === 'photo') void moPracticeThumb(img, m.item_id, api);
        else resolveThumbnail('video', m.item_id, api).then((rr) => { if (rr && (rr.path || rr.sourcePath)) setThumbImgSrc(img, rr.sourcePath || rr.path, {}); }).catch(() => {});
        it.appendChild(moEl('span', 'mo-practice-dim', { textContent: m.role === 'output' ? 'Plan output' : (m.kind === 'video' ? 'Clip' : 'Photo') }));
        const open = () => api.editors.openEditor({ typeId: 'media-organizer-grid', title: m.kind === 'video' ? 'Clip' : 'Photo', icon: m.kind === 'video' ? 'file-media' : 'image', instanceId: `detail:${m.kind}:${m.item_id}` });
        img.addEventListener('click', open);
        const rm = moEl('button', 'mo-toolbar-btn', { type: 'button', textContent: 'Remove' });
        rm.addEventListener('click', async () => { await db.run('DELETE FROM mo_plan_media WHERE id = ?', [m.id]); state.media = state.media.filter((x) => x.id !== m.id); renderPanel(); });
        it.appendChild(rm);
        list.appendChild(it);
      }
      s.appendChild(list);
    } else if (t === 'info') {
      const s = section('Plan');
      const tIn = moEl('input', 'mo-clip-input mo-clip-input--grow', { type: 'text', 'aria-label': 'Title', placeholder: 'Title' });
      tIn.value = state.plan.title || '';
      tIn.addEventListener('change', () => { state.plan.title = tIn.value.trim() || 'Painting'; titleEl.textContent = state.plan.title; scheduleSave(); });
      s.appendChild(tIn);
      const notes = moEl('textarea', 'mo-clip-input mo-plan-notes', { 'aria-label': 'Notes', placeholder: 'Notes: what the painting is about, the light, the mood, what to keep and what to leave out.' });
      notes.value = state.plan.notes || '';
      notes.addEventListener('change', () => { state.plan.notes = notes.value; scheduleSave(); });
      s.appendChild(notes);
      s.appendChild(button('Open Source Photo', () => moOpenPhotoDetail(api, state.plan.photo_id)));
      s.appendChild(button('Delete Plan', async () => {
        await db.run('DELETE FROM mo_plans WHERE id = ?', [planId]);
        document.dispatchEvent(new CustomEvent('mo:plans-changed'));
        root.innerHTML = '';
        root.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'This plan was deleted. The photo is untouched.' }));
        disposed = true;
      }));
    }
  }

  // ── palette ──
  let thumbRenderer = null; let thumbCanvas = null;
  function extractPalette() {
    if (!renderer) return;
    const small = document.createElement('canvas');
    small.width = 64; small.height = 64;
    const sctx = small.getContext('2d');
    // Off screen, through the variation-thumbnail renderer, so the stage never flashes.
    if (!thumbRenderer) { thumbCanvas = document.createElement('canvas'); thumbRenderer = moPlanRenderer(thumbCanvas); if (!thumbRenderer) return; thumbRenderer.setSource(state.image, 0); }
    const keepApply = state.recipe.palette.apply;
    state.recipe.palette.apply = false;
    thumbRenderer.render(state.recipe, { width: 128, height: 128, full: false, split: -1 });
    sctx.drawImage(thumbCanvas, 0, 0, 64, 64);
    state.recipe.palette.apply = keepApply;
    const data = sctx.getImageData(0, 0, 64, 64).data;
    const samples = [];
    for (let i = 0; i < data.length; i += 4) samples.push([data[i], data[i + 1], data[i + 2]]);
    const sw = moPlanKMeans(samples, state.recipe.palette.count || 8, 10, moPracticeRng(7));
    state.recipe.palette.swatches = sw.map((s) => s.rgb);
    afterRecipeChange(true);
  }

  // ── variations ──
  const variantThumbs = new Map();
  function renderVariants() {
    variantsBar.innerHTML = '';
    variantThumbs.clear();
    for (const v of state.variants) {
      const it = moEl('div', `mo-plan-variant${state.variant && v.id === state.variant.id ? ' is-current' : ''}${state.plan.variant_id === v.id ? ' is-kept' : ''}`);
      const img = moEl('img', null, { alt: '' });
      it.appendChild(img);
      variantThumbs.set(v.id, img);
      const name = moEl('span', null, { textContent: v.name + (state.plan.variant_id === v.id ? ' ✓' : '') });
      it.appendChild(name);
      it.addEventListener('click', () => selectVariant(v));
      variantsBar.appendChild(it);
      refreshVariantThumb(v);
    }
    const actions = moEl('div', 'mo-plan-variant-actions');
    actions.appendChild(button('Add Variation', () => void addVariant()));
    actions.appendChild(button('Keep This One', () => void keepVariant()));
    if (state.variants.length > 1) actions.appendChild(button('Remove', () => void removeVariant()));
    variantsBar.appendChild(actions);
  }
  function refreshVariantThumb(v) {
    if (!v || !state.image) return;
    const img = variantThumbs.get(v.id);
    if (!img) return;
    try {
      if (!thumbRenderer) { thumbCanvas = document.createElement('canvas'); thumbRenderer = moPlanRenderer(thumbCanvas); if (!thumbRenderer) return; thumbRenderer.setSource(state.image, 0); }
      const rs = moPlanRotatedSize(state.imgW, state.imgH, v.recipe.rotate);
      const a = (rs.w * v.recipe.crop.w) / (rs.h * v.recipe.crop.h);
      thumbRenderer.render(v.recipe, { width: Math.round(56 * Math.max(a, 0.3)), height: 56, full: false, split: -1 });
      img.src = thumbCanvas.toDataURL('image/jpeg', 0.7);
    } catch { /* no thumb */ }
  }
  function selectVariant(v) {
    state.variant = v; state.recipe = v.recipe;
    history.length = 0; histIdx = -1; pushHistory();
    if (state.recipe.blur !== state.blurBaked) bakeSource();
    renderVariants(); renderPanel(); requestRender();
  }
  async function addVariant() {
    const pos = state.variants.length;
    const name = `Variation ${pos + 1}`;
    const res = await db.run('INSERT INTO mo_plan_variants (plan_id, name, recipe_json, position) VALUES (?, ?, ?, ?)', [planId, name, JSON.stringify(state.recipe), pos]);
    const v = { id: res.lastInsertRowid, plan_id: planId, name, position: pos, recipe: moPlanNormalizeRecipe(JSON.parse(JSON.stringify(state.recipe))) };
    state.variants.push(v);
    selectVariant(v);
  }
  async function keepVariant() {
    if (!state.variant) return;
    state.plan.variant_id = state.variant.id;
    await db.run('UPDATE mo_plans SET variant_id = ?, updated_at = ? WHERE id = ?', [state.variant.id, new Date().toISOString(), planId]);
    renderVariants();
  }
  async function removeVariant() {
    if (!state.variant || state.variants.length <= 1) return;
    const gone = state.variant;
    await db.run('DELETE FROM mo_plan_variants WHERE id = ?', [gone.id]);
    state.variants = state.variants.filter((v) => v.id !== gone.id);
    if (state.plan.variant_id === gone.id) { state.plan.variant_id = state.variants[0].id; await db.run('UPDATE mo_plans SET variant_id = ? WHERE id = ?', [state.plan.variant_id, planId]); }
    selectVariant(state.variants[0]);
  }

  // ── export ──
  // Renders the recipe at full resolution into a JPEG beside the original and
  // ingests it like a scan: a photo of its own in the library.
  async function renderFull(withGrid) {
    const rs = rotated();
    const r = state.recipe;
    let W = Math.round(rs.w * r.crop.w); let H = Math.round(rs.h * r.crop.h);
    const cap = Math.min(8192, renderer.maxTexture);
    const k = Math.min(1, cap / Math.max(W, H));
    W = Math.max(1, Math.round(W * k)); H = Math.max(1, Math.round(H * k));
    const cv = document.createElement('canvas');
    const rr = moPlanRenderer(cv);
    if (!rr) throw new Error('No WebGL for the export.');
    try {
      rr.setSource(state.image, r.blur > 0 ? (r.blur * Math.max(state.imgW, state.imgH)) / 100 : 0);
      rr.render(r, { width: W, height: H, full: false, split: -1 });
      const out = document.createElement('canvas');
      out.width = W; out.height = H;
      const ctx = out.getContext('2d');
      ctx.drawImage(cv, 0, 0);
      if (withGrid) moPlanDrawOverlays(ctx, W, H, Object.assign({}, r, { overlays: Object.assign({}, r.overlays, { grid: true }) }), state.plan.canvas_w, state.plan.canvas_h, Math.max(1, W / 900));
      return out.toDataURL('image/jpeg', 0.92);
    } finally { rr.dispose(); }
  }
  async function exportPlan(withGrid) {
    if (!renderer || !state.image || !state.srcPath) return;
    exportBtn.disabled = true; exportGridBtn.disabled = true;
    try {
      const dataUrl = await renderFull(withGrid);
      const sep = state.srcPath.includes('\\') ? '\\' : '/';
      const dir = state.srcPath.slice(0, state.srcPath.lastIndexOf(sep));
      const base = state.srcPath.slice(state.srcPath.lastIndexOf(sep) + 1);
      let outPath = null;
      for (let n = 1; n < 100; n++) {
        const candidate = dir + sep + moPlanOutputName(base, n);
        if (!(await window.parallxElectron.fs.exists(candidate))) { outPath = candidate; break; }
      }
      if (!outPath) throw new Error('No free file name beside the original.');
      const res = await window.parallxElectron.fs.writeFile(outPath, dataUrl.slice(dataUrl.indexOf(',') + 1), 'base64');
      if (res && res.error) throw new Error(res.error.message || String(res.error));
      const photo = await moIngestNewImage(outPath);
      if (photo) {
        const pos = await db.get('SELECT COALESCE(MAX(position), -1) + 1 AS p FROM mo_plan_media WHERE plan_id = ?', [planId]);
        await db.run('INSERT INTO mo_plan_media (plan_id, kind, item_id, role, position, created_at) VALUES (?, ?, ?, ?, ?, ?)', [planId, 'photo', photo.id, 'output', pos ? pos.p : 0, new Date().toISOString()]);
        state.media = (await moPlanLoad(planId)).media;
        _notifySidebarRefresh();
      }
      api.window.showInformationMessage(`Plan written beside the original: ${outPath.slice(outPath.lastIndexOf(sep) + 1)}`);
    } catch (err) {
      api.window.showErrorMessage('The plan could not be exported: ' + (err && err.message));
    } finally { exportBtn.disabled = false; exportGridBtn.disabled = false; }
  }
  async function printPlan() {
    if (!renderer || !state.image) return;
    try {
      const dataUrl = await renderFull(true);
      const iframe = document.createElement('iframe');
      iframe.style.position = 'fixed'; iframe.style.right = '0'; iframe.style.bottom = '0'; iframe.style.width = '0'; iframe.style.height = '0'; iframe.style.border = '0';
      document.body.appendChild(iframe);
      const doc = iframe.contentDocument;
      doc.open();
      doc.write(`<!doctype html><title>${state.plan.title}</title><style>@page{margin:0.4in}html,body{margin:0;height:100%}body{display:flex;align-items:center;justify-content:center}img{max-width:100%;max-height:100%}</style><img src="${dataUrl}">`);
      doc.close();
      const img = doc.querySelector('img');
      const go = () => { try { iframe.contentWindow.focus(); iframe.contentWindow.print(); } catch { /* blocked */ } setTimeout(() => iframe.remove(), 60_000); };
      if (img.complete) go(); else img.onload = go;
    } catch (err) {
      api.window.showErrorMessage('The plan could not be printed: ' + (err && err.message));
    }
  }

  // ── keys ──
  root.addEventListener('keydown', (e) => {
    if (e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA')) return;
    if ((e.ctrlKey || e.metaKey) && (e.key === 'z' || e.key === 'Z')) { e.preventDefault(); if (e.shiftKey) redo(); else undo(); }
    else if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || e.key === 'Y')) { e.preventDefault(); redo(); }
  });

  // ── load ──
  (async () => {
    try {
      const data = await moPlanLoad(planId);
      if (disposed) return;
      if (!data) { root.innerHTML = ''; root.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'This plan is no longer available.' })); return; }
      state.plan = data.plan; state.variants = data.variants; state.media = data.media;
      titleEl.textContent = state.plan.title; sizeEl.textContent = `${state.plan.canvas_w} × ${state.plan.canvas_h} in`;
      state.srcPath = await moResolveItemPath({ type: 'photo', id: state.plan.photo_id });
      const url = state.srcPath ? await localFileToUrl(state.srcPath) : null;
      if (!url) { stage.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'The source photo is not on disk right now.' })); return; }
      const image = await new Promise((resolve, reject) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = () => reject(new Error('The photo could not be decoded.')); im.src = url; });
      if (disposed) return;
      state.image = image; state.imgW = image.naturalWidth; state.imgH = image.naturalHeight;
      renderer = moPlanRenderer(glCanvas);
      if (!renderer) { stage.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'WebGL is not available, so the plan cannot be shown.' })); return; }
      const v = state.variants.find((x) => x.id === state.plan.variant_id) || state.variants[0];
      if (!v) { stage.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'This plan has no variation.' })); return; }
      // A fresh plan starts with the largest crop at the canvas proportions.
      if (v.recipe.crop.w === 1 && v.recipe.crop.h === 1) { const rs = moPlanRotatedSize(state.imgW, state.imgH, v.recipe.rotate); v.recipe.crop = moPlanFitCrop(rs.w, rs.h, aspect()); }
      state.variant = v; state.recipe = v.recipe;
      bakeSource();
      pushHistory();
      renderVariants();
      setTool('light');
      root.focus();
    } catch (err) {
      if (!disposed) stage.appendChild(moEl('div', 'mo-practice-empty', { textContent: 'The plan could not load: ' + (err && err.message) }));
    }
  })();

  return {
    dispose() {
      disposed = true;
      clearTimeout(saveTimer);
      if (raf) cancelAnimationFrame(raf);
      if (resizeObs) resizeObs.disconnect();
      for (const d of panelDisposers.splice(0)) { try { d(); } catch { /* gone */ } }
      if (renderer) renderer.dispose();
      if (thumbRenderer) thumbRenderer.dispose();
      container.innerHTML = '';
    },
  };
}

// ═══════════════════════════════════════════════════════════════════════════
// IMAGE EDITOR (docs/IMAGE_EDITOR.md)
// One editor tab, modelled on Lightroom: a histogram and tool strip, sliders
// in sections (Light with a tone curve, Colour with a mixer and grading,
// Effects, Detail), Crop And Rotate, Remove, Enhance, presets and a filmstrip.
// The edit is a recipe stored per photo (mo_photo_edits); the original file is
// never touched. Save As Copy renders the recipe at full size beside the
// original; the copy is a photo of its own in the library. The engine is
// the one Painting Plans draws with.
// ═══════════════════════════════════════════════════════════════════════════

// @mo-edit-pure-begin — pure editor math (extracted verbatim by tests/unit/moImageEdit.test.ts)

// [key, label, min, max, rest, format, parent]. `rest` is the value that
// changes nothing. format: 'stops', 'pct' (shown times 100) or 'one' (one
// decimal). A slider with a parent only matters while the parent is off rest.
const MO_EDIT_LIGHT = [['exposure', 'Exposure', -2, 2, 0, 'stops'], ['contrast', 'Contrast', -1, 1, 0, 'pct'], ['highlights', 'Highlights', -1, 1, 0, 'pct'],
  ['shadows', 'Shadows', -1, 1, 0, 'pct'], ['whites', 'Whites', -1, 1, 0, 'pct'], ['blacks', 'Blacks', -1, 1, 0, 'pct']];
const MO_EDIT_COLOUR = [['warmth', 'Temperature', -1, 1, 0, 'pct'], ['tint', 'Tint', -1, 1, 0, 'pct'], ['vibrance', 'Vibrance', -1, 1, 0, 'pct'], ['saturation', 'Saturation', -1, 1, 0, 'pct']];
const MO_EDIT_EFFECTS = [['texture', 'Texture', -1, 1, 0, 'pct'], ['clarity', 'Clarity', -1, 1, 0, 'pct'], ['dehaze', 'Dehaze', -1, 1, 0, 'pct'],
  ['vignette', 'Vignette', -1, 1, 0, 'pct'], ['vignetteMid', 'Midpoint', 0, 1, 0.5, 'pct', 'vignette'], ['vignetteFeather', 'Feather', 0, 1, 0.5, 'pct', 'vignette'],
  ['grain', 'Grain', 0, 1, 0, 'pct'], ['grainSize', 'Size', 0, 1, 0.25, 'pct', 'grain']];
const MO_EDIT_DETAIL = [['sharpen', 'Sharpening', 0, 1.5, 0, 'pct'], ['sharpenRadius', 'Radius', 0.5, 3, 1, 'one', 'sharpen'],
  ['noise', 'Noise Reduction', 0, 1, 0, 'pct'], ['noiseColour', 'Colour Noise Reduction', 0, 1, 0, 'pct']];
const MO_EDIT_SLIDERS = MO_EDIT_LIGHT.concat(MO_EDIT_COLOUR, MO_EDIT_EFFECTS, MO_EDIT_DETAIL);
const MO_EDIT_SECTIONS = [['light', 'Light', MO_EDIT_LIGHT], ['colour', 'Colour', MO_EDIT_COLOUR], ['effects', 'Effects', MO_EDIT_EFFECTS], ['detail', 'Detail', MO_EDIT_DETAIL]];

// The colour mixer's eight bands: [key, label, hue in degrees].
const MO_EDIT_MIX = [['red', 'Red', 0], ['orange', 'Orange', 30], ['yellow', 'Yellow', 60], ['green', 'Green', 120],
  ['aqua', 'Aqua', 180], ['blue', 'Blue', 240], ['purple', 'Purple', 270], ['magenta', 'Magenta', 300]];
const MO_EDIT_GRADE = [['shadows', 'Shadows'], ['midtones', 'Midtones'], ['highlights', 'Highlights']];
const MO_EDIT_CURVES = [['rgb', 'All'], ['r', 'Red'], ['g', 'Green'], ['b', 'Blue']];
// [key, label, width over height]; 0 follows the photo, -1 is free.
const MO_EDIT_ASPECTS = [['original', 'Original', 0], ['free', 'Free', -1], ['1:1', '1 : 1', 1], ['4:5', '4 : 5', 0.8], ['5:7', '5 : 7', 5 / 7],
  ['2:3', '2 : 3', 2 / 3], ['3:4', '3 : 4', 0.75], ['9:16', '9 : 16', 9 / 16]];

// A 2D canvas holds at most this much (Chromium's limits); a larger result is refused, never shrunk in silence.
const MO_EDIT_MAX_PIXELS = 268435456;
const MO_EDIT_MAX_SIDE = 32767;
const MO_EDIT_TILE = 4096;
const MO_EDIT_ZOOM_MIN = 0.02;
const MO_EDIT_ZOOM_MAX = 16;
const MO_EDIT_CURVE_N = 1024;
const MO_EDIT_CURVE_MAX_POINTS = 16;
const MO_EDIT_MODEL_SIDE = 512;      // the Remove model's window, in pixels

function moEditClamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function moEditNum(v, fallback) { return v !== null && v !== '' && v !== undefined && Number.isFinite(Number(v)) ? Number(v) : fallback; }

function moEditDefaultCurve() { return { rgb: [[0, 0], [1, 1]], r: [[0, 0], [1, 1]], g: [[0, 0], [1, 1]], b: [[0, 0], [1, 1]] }; }
function moEditDefaultMixer() { const m = {}; for (const [key] of MO_EDIT_MIX) m[key] = [0, 0, 0]; return m; }
function moEditDefaultGrading() {
  const g = { blending: 0.5, balance: 0 };
  for (const [key] of MO_EDIT_GRADE) g[key] = { h: 0, s: 0, l: 0 };
  return g;
}

function moEditDefaultRecipe() {
  const r = { crop: { x: 0, y: 0, w: 1, h: 1 }, angle: 0, rotate: 0, flipH: false, flipV: false, aspect: 'original', aspectFlip: false };
  for (const [key, , , , rest] of MO_EDIT_SLIDERS) r[key] = rest;
  r.bw = false;
  r.curve = moEditDefaultCurve();
  r.mixer = moEditDefaultMixer();
  r.grading = moEditDefaultGrading();
  r.removals = [];
  r.enhance = { scale: 0, model: 'photo' };
  r.off = [];
  return r;
}

// Curve points: sorted by x, inside the square, ends pinned to the sides, no two on one x.
function moEditNormalizeCurvePoints(points) {
  const pts = (Array.isArray(points) ? points : [])
    .filter((p) => Array.isArray(p) && Number.isFinite(Number(p[0])) && Number.isFinite(Number(p[1])))
    .map((p) => [moEditClamp(Number(p[0]), 0, 1), moEditClamp(Number(p[1]), 0, 1)])
    .sort((a, b) => a[0] - b[0]);
  const out = [];
  for (const p of pts) { if (out.length && p[0] - out[out.length - 1][0] < 0.004) continue; out.push(p); }
  if (out.length < 2) return [[0, 0], [1, 1]];
  out[0][0] = 0; out[out.length - 1][0] = 1;
  if (out.length > MO_EDIT_CURVE_MAX_POINTS) out.splice(MO_EDIT_CURVE_MAX_POINTS - 1, out.length - MO_EDIT_CURVE_MAX_POINTS);
  return out;
}

// Fill in anything a stored recipe lacks and keep every number in range.
function moEditNormalizeRecipe(r) {
  const o = r && typeof r === 'object' ? r : {};
  const out = moEditDefaultRecipe();
  for (const [key, , min, max, rest] of MO_EDIT_SLIDERS) out[key] = moEditClamp(moEditNum(o[key], rest), min, max);
  out.angle = moEditClamp(moEditNum(o.angle, 0), -45, 45);
  // An upright crop lies inside the photo. A leaning one is a turned rectangle, whose box may reach past
  // the photo's sides while its corners do not: the editor checks those against the photo (moEditCropFits).
  const c = o.crop && typeof o.crop === 'object' ? o.crop : {};
  const lean = Math.abs(out.angle) > 1e-6;
  const w = moEditClamp(moEditNum(c.w, 1), 0.001, lean ? 2 : 1);
  const h = moEditClamp(moEditNum(c.h, 1), 0.001, lean ? 2 : 1);
  out.crop = lean
    ? { x: moEditClamp(moEditNum(c.x, 0), -1, 2), y: moEditClamp(moEditNum(c.y, 0), -1, 2), w, h }
    : { x: moEditClamp(moEditNum(c.x, 0), 0, 1 - w), y: moEditClamp(moEditNum(c.y, 0), 0, 1 - h), w, h };
  out.rotate = ((Math.round(moEditNum(o.rotate, 0)) % 4) + 4) % 4;
  out.flipH = o.flipH === true;
  out.flipV = o.flipV === true;
  out.aspect = MO_EDIT_ASPECTS.some((a) => a[0] === o.aspect) ? o.aspect : 'original';
  out.aspectFlip = o.aspectFlip === true;
  out.bw = o.bw === true;
  const cv = o.curve && typeof o.curve === 'object' ? o.curve : {};
  for (const [key] of MO_EDIT_CURVES) out.curve[key] = moEditNormalizeCurvePoints(cv[key]);
  const mx = o.mixer && typeof o.mixer === 'object' ? o.mixer : {};
  for (const [key] of MO_EDIT_MIX) {
    const v = Array.isArray(mx[key]) ? mx[key] : [];
    out.mixer[key] = [0, 1, 2].map((i) => moEditClamp(moEditNum(v[i], 0), -1, 1));
  }
  const gr = o.grading && typeof o.grading === 'object' ? o.grading : {};
  for (const [key] of MO_EDIT_GRADE) {
    const v = gr[key] && typeof gr[key] === 'object' ? gr[key] : {};
    out.grading[key] = { h: ((moEditNum(v.h, 0) % 1) + 1) % 1, s: moEditClamp(moEditNum(v.s, 0), 0, 1), l: moEditClamp(moEditNum(v.l, 0), -1, 1) };
  }
  out.grading.blending = moEditClamp(moEditNum(gr.blending, 0.5), 0, 1);
  out.grading.balance = moEditClamp(moEditNum(gr.balance, 0), -1, 1);
  out.removals = (Array.isArray(o.removals) ? o.removals : [])
    .filter((m) => m && typeof m.file === 'string' && m.file && [m.x, m.y, m.w, m.h].every((n) => Number.isFinite(Number(n))) && Number(m.w) > 0 && Number(m.h) > 0)
    .map((m) => ({ file: m.file, x: Math.round(Number(m.x)), y: Math.round(Number(m.y)), w: Math.round(Number(m.w)), h: Math.round(Number(m.h)) }));
  const en = o.enhance && typeof o.enhance === 'object' ? o.enhance : {};
  out.enhance = { scale: [2, 4].includes(Number(en.scale)) ? Number(en.scale) : 0, model: en.model === 'art' ? 'art' : 'photo' };
  out.off = (Array.isArray(o.off) ? o.off : []).filter((s) => MO_EDIT_SECTIONS.some((x) => x[0] === s));
  return out;
}

function moEditCurveIsRest(curve) {
  if (!curve) return true;
  for (const [key] of MO_EDIT_CURVES) {
    const p = curve[key];
    if (!p || p.length !== 2 || p[0][0] !== 0 || p[0][1] !== 0 || p[1][0] !== 1 || p[1][1] !== 1) return false;
  }
  return true;
}
function moEditMixerIsRest(mixer) {
  if (!mixer) return true;
  for (const [key] of MO_EDIT_MIX) if ((mixer[key] || []).some((v) => Math.abs(Number(v) || 0) > 1e-6)) return false;
  return true;
}
function moEditGradingIsRest(g) {
  if (!g) return true;
  for (const [key] of MO_EDIT_GRADE) { const v = g[key] || {}; if ((Number(v.s) || 0) > 1e-6 || Math.abs(Number(v.l) || 0) > 1e-6) return false; }
  return true;
}

// Which of a section's controls are off rest (the section's own, the curve with Light, the mixer and grading with Colour).
function moEditSectionIsRest(r, id) {
  const sec = MO_EDIT_SECTIONS.find((s) => s[0] === id);
  if (!sec) return true;
  for (const [key, , , , rest, , parent] of sec[2]) { if (parent) continue; if (Math.abs((Number(r[key]) || 0) - rest) > 1e-6) return false; }
  if (id === 'light') return moEditCurveIsRest(r.curve);
  if (id === 'colour') return !r.bw && moEditMixerIsRest(r.mixer) && moEditGradingIsRest(r.grading);
  return true;
}
function moEditLookIsRest(r) { return MO_EDIT_SECTIONS.every((s) => moEditSectionIsRest(r, s[0])); }
function moEditGeometryIsRest(r) {
  const c = r.crop || { x: 0, y: 0, w: 1, h: 1 };
  if (Math.abs(c.x) > 1e-6 || Math.abs(c.y) > 1e-6 || Math.abs(c.w - 1) > 1e-6 || Math.abs(c.h - 1) > 1e-6) return false;
  return !(r.angle || r.rotate || r.flipH || r.flipV);
}
// True when the recipe changes no pixel: a copy would equal the original. Enhance is not counted here.
function moEditIsNeutral(r) {
  if (!r) return true;
  return moEditLookIsRest(r) && moEditGeometryIsRest(r) && !(r.removals && r.removals.length);
}
// True when Save As Copy has something to write.
